import{a as l,b as n}from"./chunk-KYPH56UQ.js";var d=l.map(t=>{let e=n.filter(r=>r.group===t.prefix).length;return{name:t.name,nameEn:t.nameEn,icon:t.icon.replace(/^\//,""),count:e,pct:Math.round(e/n.length*100),desc:t.description,descEn:t.descriptionEn}}).filter(t=>t.count>0).sort((t,e)=>e.count-t.count),c={France:"France",Allemagne:"Germany",Japon:"Japan",Canada:"Canada"},p={"Frankfurt am Main":"Francfort"},m=(()=>{let t=new Map;for(let e of n){let[r=e.lieu,a="France"]=e.lieu.split(" - ").map(u=>u.trim()),i=p[r]??r,s=`${i}|${a}`,o=t.get(s);o?o.count++:t.set(s,{city:i,country:a,count:1})}return Array.from(t.values()).map(e=>({city:e.city,country:e.country,countryEn:c[e.country]??e.country,count:e.count,international:e.country!=="France"})).sort((e,r)=>e.international===r.international?r.count-e.count:e.international?1:-1)})(),h=[{slug:"tyroserv",publishedAt:"2026-09-26",brand:"TyroServ",logo:"assets/tyrolium-ui/projects/TyroServ-White.png",partnerCombo:{logo:"assets/tyrolium-ui/projects/TyroServ-White.png",group:"Tyrolium",name:"TyroServ"},gradient:"linear-gradient(135deg, #0000FF 0%, #BF0000 100%)",category:"Gaming \xB7 Minecraft",categoryEn:"Gaming \xB7 Minecraft",period:"2020 \u2013 2024",dataAsOf:"septembre 2026",dataAsOfEn:"September 2026",title:"Le serveur Minecraft qui a financ\xE9 un groupe",titleEn:"The Minecraft server that funded a group",summary:"Comment un serveur semi-crack lanc\xE9 en plein confinement a converti 21,8 % de ses joueurs, r\xE9uni 110 000 joueurs uniques et financ\xE9 le d\xE9marrage de Tyrolium.",summaryEn:"How a semi-crack server launched in the middle of lockdown converted 21.8% of its players, gathered 110,000 unique players and funded the start of Tyrolium.",headline:{value:"21,8 %",valueEn:"21.8%",title:"de joueurs convertis",titleEn:"of players converted"},heroStats:[{value:"110 000",valueEn:"110,000",title:"Joueurs uniques",titleEn:"Unique players"},{value:"21,8 %",valueEn:"21.8%",title:"Taux de conversion",titleEn:"Conversion rate"},{value:"160 k\u20AC",valueEn:"\u20AC160k",title:"Chiffre d'affaires 2020-2024 (environ)",titleEn:"Revenue 2020-2024 (approx.)"},{value:"8 M",valueEn:"8M",title:"T\xE9l\xE9chargements du TyroMod et du launcher",titleEn:"TyroMod and launcher downloads"}],facts:[{label:"Filiale",labelEn:"Subsidiary",value:"TyroServ"},{label:"P\xE9riode",labelEn:"Period",value:"2020 \u2013 2024"},{label:"Saisons",labelEn:"Seasons",value:"S1 \xB7 S2 \xB7 S2.5"},{label:"Mod\xE8le",labelEn:"Model",value:"Freemium semi-crack"},{label:"Briques",labelEn:"Building blocks",value:"Launcher, TyroMod, comptes Useritium, boutique int\xE9gr\xE9e",valueEn:"Launcher, TyroMod, Useritium accounts, built-in store"}],link:{label:"tyroserv.fr",url:"https://tyroserv.fr"},blocks:[{type:"text",label:"Le contexte",labelEn:"The context",title:"Printemps 2020. Des millions de jeunes enferm\xE9s chez eux.",titleEn:"Spring 2020. Millions of young people locked indoors.",paragraphs:["Le confinement vient de tomber. Minecraft devient la cour de r\xE9cr\xE9 d'une g\xE9n\xE9ration enti\xE8re. Mais pour rejoindre la plupart des grands serveurs modd\xE9s, il faut un compte officiel Mojang ou Microsoft, payant.","Les serveurs premium dominent le march\xE9, et laissent \xE0 la porte des milliers de joueurs qui n'ont pas ce compte. \xC0 l'autre extr\xEAme, les serveurs \xAB crack \xBB sont gratuits mais sans contr\xF4le : pas d'identit\xE9, de la triche partout, aucune boutique s\xE9rieuse.","Entre les deux, il y avait une place. Personne ne la prenait."],paragraphsEn:["Lockdown has just been announced. Minecraft becomes the playground of an entire generation. But to join most of the big modded servers, you need an official, paid Mojang or Microsoft account.",'Premium servers dominate the market and leave thousands of players without that account at the door. At the other extreme, "cracked" servers are free but uncontrolled: no identity, cheating everywhere, no serious store.',"There was a gap in between. Nobody was taking it."]},{type:"compare",label:"Le pari",labelEn:"The bet",title:"Le semi-crack : le meilleur des deux mondes.",titleEn:"Semi-crack: the best of both worlds.",paragraphs:["\xAB Crack \xBB, parce que TyroServ est gratuit : pas besoin d'acheter de compte Mojang ou Microsoft pour jouer.","\xAB Semi \xBB, parce que ce n'est pas un serveur ouvert \xE0 n'importe qui sans contr\xF4le : chaque joueur se connecte avec un compte maison, via notre propre launcher. Ce syst\xE8me de comptes deviendra plus tard Useritium."],paragraphsEn:['"Crack", because TyroServ is free: no need to buy a Mojang or Microsoft account to play.','"Semi", because it is not a server open to anyone with no control: every player logs in with an in-house account, through our own launcher. That account system would later become Useritium.'],columns:[{name:"Serveur crack",nameEn:"Cracked server"},{name:"Serveur premium",nameEn:"Premium server"},{name:"TyroServ semi-crack",nameEn:"TyroServ semi-crack",highlight:!0}],rows:[{label:"Acc\xE8s gratuit",labelEn:"Free access",values:[!0,!1,!0]},{label:"Comptes joueurs v\xE9rifi\xE9s",labelEn:"Verified player accounts",values:[!1,!0,!0]},{label:"Anti-triche s\xE9rieux",labelEn:"Serious anti-cheat",values:[!1,!0,!0]},{label:"Boutique li\xE9e au compte",labelEn:"Store tied to the account",values:[!1,!0,!0]}]},{type:"features",label:"Ce que \xE7a a permis",labelEn:"What it made possible",title:"Un serveur gratuit, mais haut de gamme.",titleEn:"A free server, but a premium one.",paragraphs:["Ma\xEEtriser les comptes, c'est ma\xEEtriser tout le reste. Le semi-crack n'\xE9tait pas un raccourci : c'est ce qui nous a permis de construire un serveur du niveau des meilleurs."],paragraphsEn:["Owning the accounts means owning everything else. Semi-crack was not a shortcut: it is what allowed us to build a server on par with the best."],items:[{icon:"ri-shield-check-fill",title:"Une vraie protection anti-triche",titleEn:"Real anti-cheat protection",desc:"Le launcher et le TyroMod sont les n\xF4tres : on contr\xF4le le client, pas seulement le serveur.",descEn:"The launcher and TyroMod are ours: we control the client, not just the server."},{icon:"ri-shopping-bag-3-fill",title:"Une boutique ultra int\xE9gr\xE9e",titleEn:"A deeply integrated store",desc:"Chaque achat est li\xE9 au compte du joueur et activ\xE9 automatiquement en jeu.",descEn:"Every purchase is tied to the player's account and activated automatically in game."},{icon:"ri-user-settings-fill",title:"Joueur et compte ne font qu'un",titleEn:"Player and account as one",desc:"Un compte, des statistiques, des sanctions qui tiennent : la gestion utilisateur et Minecraft sont reli\xE9es.",descEn:"One account, real stats, sanctions that stick: user management and Minecraft are linked."},{icon:"ri-palette-fill",title:"Une UX/UI soign\xE9e",titleEn:"A polished UX/UI",desc:"Launcher, site, maps personnalis\xE9es : une exp\xE9rience pens\xE9e de bout en bout.",descEn:"Launcher, website, custom maps: an experience designed end to end."}]},{type:"story",label:"L'anecdote",labelEn:"The anecdote",title:"Un lancement en pleine guerre.",titleEn:"A launch in the middle of a war.",paragraphs:["Le 26 avril 2020, TyroServ ouvre ses portes. Une semaine plus t\xF4t, je venais de me s\xE9parer de deux fondateurs historiques. Le serveur d\xE9marre avec une avalanche de bugs.","Trois jours apr\xE8s l'ouverture, l'un d'eux s'introduit dans notre base de donn\xE9es, alors bien trop mal s\xE9curis\xE9e, et menace de s'en servir. Il n'ira pas plus loin. La faille est corrig\xE9e dans la foul\xE9e, sans aucun impact pour les joueurs. Ce m\xEAme jour, TyroServ passe les 4 000 joueurs.","La fin de l'histoire ? Cet ancien fondateur travaille aujourd'hui encore pour Tyrolium. Il a fini par revenir, et il est cofondateur de SolidServ, dont il porte la strat\xE9gie."],paragraphsEn:["On 26 April 2020, TyroServ opens its doors. A week earlier, I had just parted ways with two of the historical founders. The server launches with an avalanche of bugs.","Three days after opening, one of them breaks into our database, far too poorly secured at the time, and threatens to use it. He goes no further. The flaw is fixed right away, with no impact on players. That same day, TyroServ passes 4,000 players.","The end of the story? That former founder still works for Tyrolium today. He eventually came back, and he is the co-founder of SolidServ, whose strategy he leads."],author:"Maxime Tournier",authorRole:"PDG & Fondateur de Tyrolium, fondateur de TyroServ",authorRoleEn:"CEO & Founder of Tyrolium, founder of TyroServ"},{type:"stats",label:"Les r\xE9sultats",labelEn:"The results",title:"Une traction imm\xE9diate.",titleEn:"Immediate traction.",items:[{value:"4 000",valueEn:"4,000",title:"Joueurs uniques en 4 jours",titleEn:"Unique players in 4 days"},{value:"160",title:"Joueurs connect\xE9s en permanence, en moyenne",titleEn:"Players online at all times, on average"},{value:"10 000",valueEn:"10,000",title:"Joueurs uniques en 5 mois",titleEn:"Unique players in 5 months"},{value:"8 M",valueEn:"8M",title:"T\xE9l\xE9chargements cumul\xE9s sur CurseForge et GitHub",titleEn:"Cumulative downloads on CurseForge and GitHub"}],note:"Le TyroMod est rendu open-source \xE0 la fermeture de chaque saison et publi\xE9 sur CurseForge et GitHub. La grande majorit\xE9 de ces 8 millions de t\xE9l\xE9chargements vient de joueurs qui l'utilisent en dehors de TyroServ.",noteEn:"TyroMod is made open source when each season closes and published on CurseForge and GitHub. The vast majority of these 8 million downloads come from players who use it outside TyroServ."},{type:"bars",label:"Sur trois saisons",labelEn:"Over three seasons",title:"110 000 joueurs uniques.",titleEn:"110,000 unique players.",note:"La saison 1 a dur\xE9 d'avril 2020 \xE0 f\xE9vrier 2021. Apr\xE8s 10 000 joueurs en 5 mois, le deuxi\xE8me confinement, \xE0 partir d'octobre 2020, a fait exploser la fr\xE9quentation.",noteEn:"Season 1 ran from April 2020 to February 2021. After 10,000 players in 5 months, the second lockdown, from October 2020, sent attendance soaring.",items:[{title:"Saison 1",titleEn:"Season 1",pct:38,value:"~41 800",valueEn:"~41,800"},{title:"Saison 2",titleEn:"Season 2",pct:40,value:"~44 000",valueEn:"~44,000"},{title:"Saison 2.5",titleEn:"Season 2.5",pct:22,value:"~24 200",valueEn:"~24,200"}]},{type:"features",label:"Pourquoi 21,8 %",labelEn:"Why 21.8%",title:"Plus d'un joueur sur cinq est pass\xE9 \xE0 la boutique.",titleEn:"More than one player in five made a purchase.",paragraphs:["Un taux rarement atteint dans le secteur. Il ne tient pas \xE0 une astuce, mais \xE0 un ensemble de choix."],paragraphsEn:["A rate rarely reached in the industry. It is not down to one trick, but to a set of choices."],items:[{icon:"ri-gift-fill",title:"Le mod\xE8le freemium",titleEn:"The freemium model",desc:"Entrer ne co\xFBtait rien. Payer devenait un choix, pas une barri\xE8re.",descEn:"Getting in cost nothing. Paying became a choice, not a barrier."},{icon:"ri-price-tag-3-fill",title:"Des prix bas",titleEn:"Low prices",desc:"Un panier moyen autour de 5 \u20AC : un achat accessible, m\xEAme pour un adolescent.",descEn:"An average basket around \u20AC5: an affordable purchase, even for a teenager."},{icon:"ri-discord-fill",title:"Une \xE9quipe proche",titleEn:"A close team",desc:"Une \xE9quipe accessible sur Discord, qui donnait envie de soutenir un petit projet.",descEn:"A team reachable on Discord, which made people want to support a small project."},{icon:"ri-group-fill",title:"La communaut\xE9 et le Covid",titleEn:"Community and Covid",desc:"Un lieu de rendez-vous pendant le confinement, o\xF9 les amis se retrouvaient.",descEn:"A meeting place during lockdown, where friends got together."},{icon:"ri-refresh-fill",title:"Une vraie continuit\xE9",titleEn:"Real continuity",desc:"Un serveur suivi et mis \xE0 jour : ce qu'on achetait avait de la valeur dans la dur\xE9e.",descEn:"A maintained, updated server: what you bought kept its value over time."},{icon:"ri-shield-star-fill",title:"Anti-triche et UX",titleEn:"Anti-cheat and UX",desc:"Un environnement propre et agr\xE9able, o\xF9 on a envie de rester.",descEn:"A clean, pleasant environment you want to stay in."}]},{type:"stats",label:"L'argent",labelEn:"The money",title:"Et o\xF9 il est all\xE9.",titleEn:"And where it went.",items:[{value:"160 k\u20AC",valueEn:"\u20AC160k",title:"Chiffre d'affaires cumul\xE9 de 2020 \xE0 2024, environ",titleEn:"Cumulative revenue from 2020 to 2024, approx."},{value:"5 \u20AC",valueEn:"\u20AC5",title:"Panier moyen par vente, environ",titleEn:"Average basket per sale, approx."},{value:"33 k\u20AC",valueEn:"\u20AC33k",title:"En un seul mois : le record absolu de Tyrolium",titleEn:"In a single month: Tyrolium's all-time record"}],paragraphs:["Les d\xE9veloppeurs de la premi\xE8re heure ont \xE9t\xE9 r\xE9mun\xE9r\xE9s en pourcentage de la r\xE9ussite de la saison 1 : ils ont \xE9t\xE9 bien pay\xE9s.","Et surtout, cet argent a financ\xE9 SolidServ : des serveurs achet\xE9s cash, qui ont ensuite port\xE9 la saison 2, la saison 2.5 et le d\xE9marrage de tous les projets de Tyrolium."],paragraphsEn:["The early developers were paid a percentage of season 1's success: they were paid well.","Above all, that money funded SolidServ: servers bought outright, which then powered season 2, season 2.5 and the start of every Tyrolium project."]},{type:"features",label:"L'h\xE9ritage",labelEn:"The legacy",title:"Ce que TyroServ a fait na\xEEtre.",titleEn:"What TyroServ gave birth to.",items:[{icon:"ri-server-fill",title:"SolidServ",titleEn:"SolidServ",desc:"Gr\xE2ce \xE0 TyroServ, nos serveurs ont \xE9t\xE9 achet\xE9s cash au lieu d'\xEAtre lou\xE9s. Nous \xE9tions d\xE9j\xE0 chez OVH, en France : l'ind\xE9pendance n'\xE9tait pas qu'id\xE9ologique, elle est devenue \xE9conomique. Des serveurs \xE0 tr\xE8s bas co\xFBt, qui nous permettent d'ouvrir de nombreux projets.",descEn:"Thanks to TyroServ, our servers were bought outright instead of rented. We were already with OVH, in France: independence was not only ideological, it became economic. Very low-cost servers that let us launch many projects."},{icon:"ri-fingerprint-fill",title:"Useritium",titleEn:"Useritium",desc:"Le syst\xE8me de comptes maison du semi-crack est devenu Useritium, les comptes universels de tout le groupe.",descEn:"The semi-crack's in-house account system became Useritium, the universal accounts of the whole group."},{icon:"ri-tools-fill",title:"Les prestations",titleEn:"Our services",desc:"Le savoir-faire acquis sur TyroServ est aujourd'hui vendu aux autres serveurs Minecraft.",descEn:"The know-how gained on TyroServ is now sold to other Minecraft servers."},{icon:"ri-restart-fill",title:"Un serveur pr\xEAt \xE0 repartir",titleEn:"A server ready to relaunch",desc:"Infrastructure, outils, \xE9quipe : aujourd'hui, relancer TyroServ ne nous co\xFBte presque plus rien.",descEn:"Infrastructure, tools, team: today, relaunching TyroServ costs us almost nothing."}]},{type:"features",label:"Les le\xE7ons",labelEn:"The lessons",title:"Ce que nous en retenons.",titleEn:"What we take away.",items:[{icon:"ri-lightbulb-flash-fill",title:"Le gratuit bien fait vend",titleEn:"Free done right sells",desc:"Ouvrir les portes n'emp\xEAche pas de vendre. \xC7a multiplie ceux qui peuvent acheter.",descEn:"Opening the doors does not stop you selling. It multiplies the people who can buy."},{icon:"ri-hand-heart-fill",title:"La proximit\xE9 est un avantage",titleEn:"Closeness is an advantage",desc:"Une \xE9quipe accessible cr\xE9e une communaut\xE9 qui a envie de vous voir r\xE9ussir.",descEn:"An accessible team builds a community that wants to see you succeed."},{icon:"ri-key-2-fill",title:"Poss\xE9der, plut\xF4t que louer",titleEn:"Own, rather than rent",desc:"Comptes, launcher, serveurs : tout ce que l'on poss\xE8de, on le contr\xF4le et on le rentabilise.",descEn:"Accounts, launcher, servers: whatever you own, you control and make pay off."}]}],cta:{title:"Vous lancez un serveur Minecraft ?",titleEn:"Launching a Minecraft server?",content:"Tout ce que nous avons appris sur TyroServ, nous le mettons au service de votre projet : infrastructure, launcher, boutique, communaut\xE9.",contentEn:"Everything we learned on TyroServ, we put to work for your project: infrastructure, launcher, store, community.",btn:"D\xE9couvrir nos prestations Minecraft",btnEn:"Discover our Minecraft services",btnIcon:"ri-sword-line",routerLink:"/prestation/minecraft"}},{slug:"cabinet-marthelot",publishedAt:"2026-09-26",brand:"Cabinet Marthelot",brandFr:"le Cabinet Marthelot",logo:"assets/tyrolium-ui/projects/Tyrolium-White.png",partnerLogo:"assets/etudes/cabinet-marthelot-white.png",gradient:"linear-gradient(135deg, #0000FF 0%, #BF0000 100%)",category:"Web \xB7 Partenariat",categoryEn:"Web \xB7 Partnership",period:"Depuis juillet 2026",periodEn:"Since July 2026",dataAsOf:"octobre 2026",dataAsOfEn:"October 2026",title:"Un site pro offert, financ\xE9 par l'h\xE9bergement",titleEn:"A professional website, paid for by hosting",summary:"Avec le Cabinet Marthelot, nous offrons \xE0 des artisans, ind\xE9pendants et TPE un site vitrine d\xE9velopp\xE9 par nos \xE9quipes, sans co\xFBt de cr\xE9ation : seul l'h\xE9bergement est payant, en abonnement.",summaryEn:"With Cabinet Marthelot, we give craftspeople, freelancers and small businesses a showcase website built by our team, with no build cost: only the hosting is paid, as a subscription.",headline:{value:"0 \u20AC",valueEn:"\u20AC0",title:"de cr\xE9ation factur\xE9e au client",titleEn:"build cost for the client"},heroStats:[{value:"0 \u20AC",valueEn:"\u20AC0",title:"Cr\xE9ation du site factur\xE9e",titleEn:"Website build cost"},{value:"7 jours",valueEn:"7 days",title:"D\xE9lai de livraison maximum",titleEn:"Maximum delivery time"},{value:".fr",title:"Uniquement des domaines fran\xE7ais",titleEn:"French domains only"},{value:"4",title:"Entreprises d\xE9j\xE0 \xE9quip\xE9es",titleEn:"Businesses already equipped"}],facts:[{label:"Partenaire",labelEn:"Partner",value:"Cabinet Marthelot"},{label:"Pour qui",labelEn:"For whom",value:"Professions lib\xE9rales, artisans, auto-entrepreneurs, TPE et PME",valueEn:"Liberal professions, craftspeople, sole traders, small businesses"},{label:"Offre",labelEn:"Offer",value:"Site vitrine offert + h\xE9bergement SolidServ",valueEn:"Free showcase website + SolidServ hosting"},{label:"D\xE9lai",labelEn:"Delivery",value:"5 \xE0 7 jours",valueEn:"5 to 7 days"},{label:"Domaines",labelEn:"Domains",value:".fr uniquement",valueEn:".fr only"},{label:"Depuis",labelEn:"Since",value:"Juillet 2026",valueEn:"July 2026"}],link:{label:"fernando-paysagiste.fr",url:"https://fernando-paysagiste.fr"},blocks:[{type:"text",label:"Le constat",labelEn:"The problem",title:"Un site co\xFBte cher, surtout quand on se lance.",titleEn:"A website is expensive, especially when you are starting out.",paragraphs:["Un artisan, un paysagiste, une profession lib\xE9rale : tous ont besoin d'\xEAtre trouv\xE9s en ligne. Mais un site r\xE9alis\xE9 par des professionnels se paie entre 450 et 1 200 \u20AC, d'un coup, au moment m\xEAme o\xF9 chaque euro compte.","R\xE9sultat : beaucoup s'en passent, ou bricolent un site qui ne leur ressemble pas. Ils perdent des clients sans le savoir."],paragraphsEn:["A craftsperson, a landscaper, a liberal professional: they all need to be found online. But a professionally built website costs between \u20AC450 and \u20AC1,200, all at once, at the very moment every euro counts.","The result: many go without, or cobble together a site that does not look like them. They lose customers without knowing it."]},{type:"steps",label:"Le mod\xE8le",labelEn:"The model",title:"Le site est offert. L'h\xE9bergement fait tourner le mod\xE8le.",titleEn:"The website is free. Hosting keeps the model running.",items:[{title:"Le client rejoint le Cabinet Marthelot",titleEn:"The client joins Cabinet Marthelot",desc:"Il choisit l'option site web dans l'offre d'accompagnement du cabinet.",descEn:"They pick the website option in the firm's support package."},{title:"Le premier mois est r\xE9gl\xE9",titleEn:"The first month is paid",desc:"D\xE8s r\xE9ception, notre \xE9quipe lance le d\xE9veloppement.",descEn:"As soon as it is received, our team starts building."},{title:"Le site est livr\xE9 en 5 \xE0 7 jours",titleEn:"The site is delivered in 5 to 7 days",desc:"Design sur mesure, domaine en .fr, h\xE9berg\xE9 sur les serveurs SolidServ en France.",descEn:"Custom design, .fr domain, hosted on SolidServ servers in France."},{title:"Le site vit avec l'abonnement",titleEn:"The site lives with the subscription",desc:"Tant que l'abonnement court, le site reste en ligne et maintenu. S'il s'arr\xEAte, le site est coup\xE9 apr\xE8s un d\xE9lai d'une semaine.",descEn:"As long as the subscription runs, the site stays online and maintained. If it stops, the site is taken down after a one-week grace period."}],note:"La facturation passe par le cabinet : client final \u2192 Cabinet Marthelot \u2192 Tyrolium. Le cabinet fixe librement son prix, Tyrolium se r\xE9mun\xE8re sur l'h\xE9bergement.",noteEn:"Billing goes through the firm: end client \u2192 Cabinet Marthelot \u2192 Tyrolium. The firm sets its own price; Tyrolium is paid through hosting."},{type:"testimonial",quote:"Chez les artisans, ind\xE9pendants et TPE que j'accompagne au Cabinet Marthelot, je constatais souvent un manque d'image professionnelle et de site web adapt\xE9 par manque de budget ou de temps. En int\xE9grant Tyrolium et sa filiale SolidServ dans notre accompagnement, nos clients b\xE9n\xE9ficient imm\xE9diatement d'un site vitrine complet, h\xE9berg\xE9 et ultra-accessible, sans lourds frais de cr\xE9ation initiaux. Pour notre cabinet, c'est l'opportunit\xE9 d'offrir une r\xE9ponse globale d\xE8s la premi\xE8re \xE9tape de leur d\xE9veloppement en clarifiant leur proposition de valeur. Au quotidien, la collaboration est fluide et efficace : apr\xE8s notre \xE9tude de leurs besoins, Tyrolium prend le relais avec r\xE9activit\xE9 pour concevoir une vitrine claire et sur-mesure. Retravailler avec Tyrolium, avec qui j'ai d\xE9j\xE0 travaill\xE9 dans le pass\xE9, apporte une confiance totale et naturelle dans cette synergie.",quoteEn:"Among the craftspeople, freelancers and small businesses I support at Cabinet Marthelot, I often saw a lack of professional image and of a suitable website, for lack of budget or time. By bringing Tyrolium and its subsidiary SolidServ into our support package, our clients immediately get a complete showcase website, hosted and highly accessible, with no heavy upfront build costs. For our firm, it is the opportunity to offer a complete answer from the very first stage of their growth, by clarifying their value proposition. Day to day, the collaboration is smooth and efficient: after we study their needs, Tyrolium quickly takes over to design a clear, tailor-made showcase. Working with Tyrolium again, having worked with them in the past, brings complete and natural trust to this partnership.",author:"Ma\xEBwan Marthelot",authorRole:"Pr\xE9sident du Cabinet Marthelot",authorRoleEn:"President of Cabinet Marthelot \xB7 translated from French",photo:"assets/teams/Maewan_Marthelot.jpg"},{type:"text",label:"Pourquoi on peut l'offrir",labelEn:"Why we can offer it",title:"Parce que nous poss\xE9dons nos serveurs.",titleEn:"Because we own our servers.",paragraphs:["Gr\xE2ce \xE0 TyroServ, SolidServ a achet\xE9 ses machines au lieu de les louer. H\xE9berger un site vitrine de plus ne nous co\xFBte presque rien.","Un h\xE9bergeur qui loue ses serveurs ne peut pas offrir le d\xE9veloppement : chaque site lui co\xFBte chaque mois. Nous, l'abonnement rembourse la cr\xE9ation sur la dur\xE9e, puis devient un revenu r\xE9current. C'est un mod\xE8le que seule une infrastructure ma\xEEtris\xE9e rend possible."],paragraphsEn:["Thanks to TyroServ, SolidServ bought its machines instead of renting them. Hosting one more showcase site costs us almost nothing.","A host that rents its servers cannot give away the build: every site costs it money every month. For us, the subscription pays back the build over time, then becomes recurring revenue. It is a model only an infrastructure you control makes possible."],linkLabel:"Lire l'\xE9tude de cas TyroServ",linkLabelEn:"Read the TyroServ case study",linkRouter:"/etudes-de-cas/tyroserv"},{type:"compare",label:"Pour le client",labelEn:"For the client",paragraphs:["Sans budget, beaucoup se tournent vers un site fait soi-m\xEAme : pas de co\xFBt de cr\xE9ation, mais un mod\xE8le g\xE9n\xE9rique, des heures perdues, et des mises \xE0 jour, de la s\xE9curit\xE9 et des extensions \xE0 g\xE9rer seul. Le site finit souvent \xE0 l'abandon."],paragraphsEn:["Without a budget, many turn to a do-it-yourself site: no build cost, but a generic template, hours lost, and updates, security and plugins to manage alone. The site often ends up abandoned."],title:"Trois fa\xE7ons d'avoir un site.",titleEn:"Three ways to get a website.",columns:[{name:"Site fait soi-m\xEAme (WordPress, Wix\u2026)",nameEn:"DIY website (WordPress, Wix\u2026)"},{name:"Site sur devis (450 \xE0 1 200 \u20AC)",nameEn:"Quoted website (\u20AC450 to \u20AC1,200)"},{name:"Site offert (partenariat)",nameEn:"Free website (partnership)",highlight:!0}],rows:[{label:"Aucun co\xFBt de cr\xE9ation",labelEn:"No build cost",values:[!0,!1,!0]},{label:"R\xE9alis\xE9 par des d\xE9veloppeurs professionnels",labelEn:"Built by professional developers",values:[!1,!0,!0]},{label:"Design sur mesure",labelEn:"Custom design",values:[!1,!0,!0]},{label:"H\xE9bergement et maintenance compris",labelEn:"Hosting and maintenance included",values:[!1,!1,!0]}]},{type:"features",label:"Le cadre",labelEn:"The scope",title:"Simple, par choix.",titleEn:"Simple, by design.",paragraphs:["Pour livrer en moins d'une semaine sans rien facturer \xE0 la cr\xE9ation, le p\xE9rim\xE8tre est volontairement clair : des sites vitrines, sans back-office complexe."],paragraphsEn:["To deliver in under a week without charging for the build, the scope is deliberately clear: showcase websites, with no complex back office."],items:[{icon:"ri-palette-fill",title:"Un design sur mesure",titleEn:"A custom design",desc:"Une interface pens\xE9e pour le m\xE9tier du client, pas un mod\xE8le g\xE9n\xE9rique.",descEn:"An interface designed for the client's trade, not a generic template."},{icon:"ri-links-fill",title:"Liens et redirections",titleEn:"Links and redirects",desc:"R\xE9seaux sociaux, t\xE9l\xE9phone, avis, prise de rendez-vous.",descEn:"Social networks, phone, reviews, bookings."},{icon:"ri-mail-send-fill",title:"Un formulaire de contact",titleEn:"A contact form",desc:"Pour recevoir les demandes de devis, sans d\xE9veloppement complexe.",descEn:"To receive quote requests, without complex development."},{icon:"ri-flag-2-fill",title:"Un domaine en .fr",titleEn:"A .fr domain",desc:"Uniquement des domaines fran\xE7ais, h\xE9berg\xE9s en France.",descEn:"French domains only, hosted in France."}]},{type:"showcase",label:"R\xE9alisation",labelEn:"Showcase",title:"Fernando Paysagiste.",titleEn:"Fernando Paysagiste.",paragraphs:["Auto-entreprise de proximit\xE9 sp\xE9cialis\xE9e dans la cr\xE9ation et l'entretien d'espaces verts, sur le secteur de Nancy et ses alentours. Le site met en avant les services et les chantiers r\xE9alis\xE9s, et permet de demander un devis en deux clics."],paragraphsEn:["A local sole-trader business specialising in creating and maintaining green spaces, in and around Nancy. The site showcases services and completed projects, and lets visitors request a quote in two clicks."],image:"assets/etudes/fernando-paysagiste.jpg",imageAlt:"Page d'accueil du site fernando-paysagiste.fr",url:"https://fernando-paysagiste.fr",urlLabel:"fernando-paysagiste.fr"},{type:"testimonial",quote:"Apr\xE8s ces quelques jours de boulot, le rendu est vraiment propre. L'offre est claire, les chantiers sont mis en valeur, et si un client veut un devis, il nous trouve en deux clics. C'est pro, c'est efficace, exactement ce qu'il nous fallait. Merci au Cabinet Marthelot et \xE0 sa collaboration avec Tyrolium pour ce site vitrine qui a su repr\xE9senter mon domaine et mon entreprise !",quoteEn:"After just a few days of work, the result is really clean. The offer is clear, our projects are showcased, and if a customer wants a quote, they find us in two clicks. It's professional, it's effective, exactly what we needed. Thanks to Cabinet Marthelot and its partnership with Tyrolium for this showcase website, which truly represents my trade and my business!",author:"Fernando",authorRole:"Fernando Paysagiste, Nancy et alentours",authorRoleEn:"Fernando Paysagiste, Nancy area \xB7 translated from French"},{type:"features",label:"Gagnant-gagnant",labelEn:"Win-win",title:"Trois gagnants, z\xE9ro perdant.",titleEn:"Three winners, no losers.",items:[{icon:"ri-store-2-fill",title:"Le client",titleEn:"The client",desc:"Un site professionnel, sans avancer le prix de la cr\xE9ation, h\xE9berg\xE9 et maintenu.",descEn:"A professional website, without paying for the build upfront, hosted and maintained."},{icon:"ri-briefcase-4-fill",title:"Le cabinet",titleEn:"The firm",desc:"Une offre d'accompagnement plus compl\xE8te, avec un vrai site int\xE9gr\xE9 \xE0 la formule.",descEn:"A more complete support package, with a real website built into it."},{icon:"ri-server-fill",title:"Tyrolium",titleEn:"Tyrolium",desc:"Des clients apport\xE9s par le cabinet, un revenu r\xE9current et des serveurs rentabilis\xE9s.",descEn:"Clients brought in by the firm, recurring revenue and servers that pay for themselves."}]},{type:"story",label:"L'anecdote",labelEn:"The anecdote",title:"Un partenaire qui vient de la maison.",titleEn:"A partner who grew up with us.",paragraphs:["Avant le Cabinet Marthelot, il y avait MA3WAN : la cha\xEEne YouTube de Ma\xEBwan, son tout premier projet. Puis il a rejoint Tyrolium, et il y est rest\xE9 des ann\xE9es.","Chez nous, il a cofond\xE9 Influnias, toujours active aujourd'hui, et Duo-Gramme, une ancienne filiale du groupe. Surtout, il a port\xE9 une grande partie de la communication de Tyrolium et de sa strat\xE9gie.","Quand il a fond\xE9 sa propre soci\xE9t\xE9 pour accompagner les entrepreneurs, travailler ensemble \xE9tait une \xE9vidence. Lui conna\xEEt ses clients et leur m\xE9tier, nous savons construire et h\xE9berger leur site : chacun fait ce qu'il sait faire de mieux."],paragraphsEn:["Before Cabinet Marthelot, there was MA3WAN: Ma\xEBwan's YouTube channel, his very first project. Then he joined Tyrolium, and stayed for years.","With us, he co-founded Influnias, still active today, and Duo-Gramme, a former subsidiary of the group. Above all, he drove a large part of Tyrolium's communication and strategy.","When he founded his own company to support entrepreneurs, working together was obvious. He knows his clients and their trades; we know how to build and host their website: everyone does what they do best."],author:"Maxime Tournier",authorRole:"PDG & Fondateur de Tyrolium",authorRoleEn:"CEO & Founder of Tyrolium"},{type:"features",label:"Les le\xE7ons",labelEn:"The lessons",title:"Ce que nous en retenons.",titleEn:"What we take away.",items:[{icon:"ri-door-open-fill",title:"Le prix d'entr\xE9e est le premier frein",titleEn:"The entry price is the first barrier",desc:"Supprimer le co\xFBt de d\xE9part change tout pour un entrepreneur qui se lance.",descEn:"Removing the upfront cost changes everything for an entrepreneur starting out."},{icon:"ri-team-fill",title:"Un bon partenaire vaut une \xE9quipe commerciale",titleEn:"A good partner is worth a sales team",desc:"Le cabinet conna\xEEt ses clients et leur confiance lui appartient : nous nous concentrons sur la technique.",descEn:"The firm knows its clients and owns their trust: we focus on the technology."},{icon:"ri-key-2-fill",title:"Poss\xE9der son infrastructure ouvre des mod\xE8les",titleEn:"Owning your infrastructure unlocks models",desc:"Offrir le d\xE9veloppement n'est possible que parce que nos serveurs nous appartiennent.",descEn:"Giving away the build is only possible because we own our servers."}]}],cta:{title:"Vous accompagnez des entrepreneurs ?",titleEn:"Do you support entrepreneurs?",content:"Cabinet de conseil, expert-comptable, r\xE9seau d'ind\xE9pendants : proposez un site professionnel \xE0 vos clients, sans rien d\xE9velopper vous-m\xEAme.",contentEn:"Consulting firm, accountant, network of freelancers: offer your clients a professional website, without building anything yourself.",btn:"Devenir partenaire",btnEn:"Become a partner",btnIcon:"ri-shake-hands-line",routerLink:"/contact"}},{slug:"tyrostage",publishedAt:"2026-09-26",brand:"TyroStage",logo:"assets/tyrolium-ui/projects/Tyrolium-White.png",partnerCombo:{logo:"assets/tyrolium-ui/projects/Tyrolium-White.png",name:"Tyrolium"},gradient:"linear-gradient(135deg, #0000FF 0%, #BF0000 100%)",category:"Recrutement \xB7 Formation",categoryEn:"Recruitment \xB7 Training",period:"Saisons 1 \xE0 6",periodEn:"Seasons 1 to 6",dataAsOf:"septembre 2026",dataAsOfEn:"September 2026",title:"Nous ne lisons pas les CV. Nous regardons les gens travailler.",titleEn:"We don't read CVs. We watch people work.",summary:"TyroStage, c'est notre m\xE9thode de recrutement : rep\xE9rer les talents pendant nos formations en \xE9cole, sur des semaines de pratique r\xE9elle, plut\xF4t que sur un CV et un entretien d'une heure.",summaryEn:"TyroStage is our recruitment method: spotting talent during our school training sessions, over weeks of real practice, rather than from a CV and a one-hour interview.",headline:{value:"19",title:"stagiaires form\xE9s sur 6 saisons",titleEn:"interns trained over 6 seasons"},heroStats:[{value:"6",title:"Saisons TyroStage",titleEn:"TyroStage seasons"},{value:"19",title:"Stagiaires accueillis",titleEn:"Interns welcomed"},{value:"2",title:"\xC9coles partenaires",titleEn:"Partner schools"},{value:"0",title:"Recrutement sur la base du dipl\xF4me",titleEn:"Hires based on a diploma"}],facts:[{label:"Programme",labelEn:"Programme",value:"TyroStage"},{label:"\xC9coles",labelEn:"Schools",value:"Human Booster, IPSSI"},{label:"Format",labelEn:"Format",value:"Formation en \xE9cole, puis stage en groupe",valueEn:"School training, then group internship"},{label:"Par saison",labelEn:"Per season",value:"3 \xE0 5 stagiaires, souvent un groupe d'amis",valueEn:"3 to 5 interns, often a group of friends"},{label:"Crit\xE8re n\xB01",labelEn:"Criterion #1",value:"La soif d'apprendre",valueEn:"Hunger to learn"}],blocks:[{type:"text",label:"Le constat",labelEn:"The problem",title:"Un CV dit ce qu'on a fait. Pas ce qu'on vaut.",titleEn:"A CV says what you have done. Not what you are worth.",paragraphs:["Dans la tech, le dipl\xF4me certifie un parcours. Il ne garantit ni la passion, ni la r\xE9silience face \xE0 un probl\xE8me qui r\xE9siste. Et un entretien d'une heure en dit encore moins : on y juge surtout la capacit\xE9 \xE0 bien parler de soi.","Nous avons pris le probl\xE8me \xE0 l'envers. Plut\xF4t que de lire des CV, nous observons des gens travailler, pendant des semaines, sur de vrais probl\xE8mes."],paragraphsEn:["In tech, a diploma certifies a path. It guarantees neither passion nor resilience against a problem that will not give in. And a one-hour interview says even less: it mostly judges how well someone talks about themselves.","We flipped the problem. Instead of reading CVs, we watch people work, for weeks, on real problems."]},{type:"features",label:"Le terrain",labelEn:"The ground",title:"La formation comme une vraie entreprise.",titleEn:"Training run like a real company.",paragraphs:["Le fondateur de Tyrolium est aussi formateur en d\xE9veloppement et en administration syst\xE8me dans des \xE9coles sup\xE9rieures. Ses cours ne sont pas de la th\xE9orie : chaque promotion fonctionne comme une mini-entreprise, avec des clients, des responsabilit\xE9s et un patron, le formateur."],paragraphsEn:["Tyrolium's founder is also a trainer in development and system administration at higher-education schools. His courses are not theory: each class runs as a mini-company, with clients, responsibilities and a boss, the trainer."],items:[{icon:"ri-stack-fill",title:"Des produits r\xE9els",titleEn:"Real products",desc:"Les exercices reprennent des produits que nous avons d\xE9velopp\xE9s. Une fois l'exercice rendu, on montre la version sortie par Tyrolium.",descEn:"Exercises are based on products we have built. Once the exercise is handed in, we show the version Tyrolium actually shipped."},{icon:"ri-timer-flash-fill",title:"Des d\xE9lais serr\xE9s",titleEn:"Tight deadlines",desc:"Des \xE9ch\xE9ances parfois difficiles \xE0 tenir, comme sur le terrain. C'est sous la pression qu'on voit vraiment les gens.",descEn:"Deadlines that are sometimes hard to meet, like in the field. Pressure is where you really see people."},{icon:"ri-user-voice-fill",title:"Un client \xE0 convaincre",titleEn:"A client to convince",desc:"\xC0 chaque pr\xE9sentation de projet, le formateur joue le r\xF4le du client : exigences, retours, changements de derni\xE8re minute.",descEn:"At every project presentation, the trainer plays the client: demands, feedback, last-minute changes."},{icon:"ri-eye-fill",title:"Des semaines d'observation",titleEn:"Weeks of observation",desc:"L\xE0 o\xF9 un entretien dure une heure, la formation montre chacun pendant des semaines : code, d\xE9ploiement, d\xE9bogage, travail d'\xE9quipe.",descEn:"Where an interview lasts an hour, training shows everyone for weeks: code, deployment, debugging, teamwork."}]},{type:"steps",label:"La m\xE9thode",labelEn:"The method",title:"Du cours au contrat, en cinq \xE9tapes.",titleEn:"From class to contract, in five steps.",items:[{title:"Comprendre chaque objectif",titleEn:"Understand each goal",desc:"D\xE8s le d\xE9but, le formateur demande \xE0 chacun ce qu'il vise. \xC7a sert \xE0 adapter la p\xE9dagogie, et \xE0 rep\xE9rer les projets qui rejoignent ceux de Tyrolium.",descEn:"From day one, the trainer asks everyone what they are aiming for. It helps tailor the teaching, and spot goals that align with Tyrolium's."},{title:"Observer en situation r\xE9elle",titleEn:"Observe in real conditions",desc:"Pendant toute la formation : la curiosit\xE9, la logique, la r\xE9silience, et la fa\xE7on de traiter les autres.",descEn:"Throughout the training: curiosity, logic, resilience, and how people treat others."},{title:"Former un groupe",titleEn:"Build a group",desc:"Apr\xE8s l'intervention, 3 \xE0 5 personnes d'une promotion de 15 \xE0 30 rejoignent l'aventure, souvent un groupe d'amis. La proposition vient de nous, ou d'un \xE9tudiant qui ose demander.",descEn:"After the course, 3 to 5 people from a class of 15 to 30 join the adventure, often a group of friends. The offer comes from us, or from a student bold enough to ask."},{title:"Une saison TyroStage",titleEn:"A TyroStage season",desc:"Chaque groupe forme une saison : plusieurs mois de stage sur les vrais projets du groupe, encadr\xE9s par le fondateur, qui leur permettent de valider leur dipl\xF4me.",descEn:"Each group becomes a season: several months of internship on the group's real projects, supervised by the founder, which let them complete their degree."},{title:"Recruter, ou lancer",titleEn:"Hire, or launch",desc:"\xC0 la fin, on garde g\xE9n\xE9ralement une personne, rarement deux, selon la suite de leurs \xE9tudes et leur envie de start-up. D'autres lancent leur activit\xE9, accompagn\xE9s par Tyrolium.",descEn:"At the end, we usually keep one person, rarely two, depending on their further studies and appetite for a start-up. Others launch their own business, supported by Tyrolium."}]},{type:"features",label:"Ce que nous cherchons",labelEn:"What we look for",title:"La soif avant le niveau.",titleEn:"Hunger before skill level.",paragraphs:["Nous ne cherchons pas des brutes techniques. La technique, nous savons la transmettre : nous le faisons \xE0 chaque saison. Ce qui ne s'apprend pas, c'est le reste."],paragraphsEn:["We are not looking for technical prodigies. Technique is something we know how to teach: we do it every season. What cannot be taught is everything else."],items:[{icon:"ri-fire-fill",title:"La soif",titleEn:"Hunger",desc:"L'envie d'apprendre, de comprendre, d'aller plus loin que ce qu'on demande.",descEn:"The drive to learn, to understand, to go further than what is asked."},{icon:"ri-bug-fill",title:"La r\xE9silience",titleEn:"Resilience",desc:"\xCAtre capable de passer huit heures d'affil\xE9e sur le m\xEAme bug, sans l\xE2cher.",descEn:"Being able to spend eight hours straight on the same bug, without giving up."},{icon:"ri-heart-3-fill",title:"La bienveillance",titleEn:"Kindness",desc:"Aider les autres, respecter l'\xE9quipe. Non n\xE9gociable.",descEn:"Helping others, respecting the team. Non-negotiable."},{icon:"ri-gamepad-fill",title:"La passion",titleEn:"Passion",desc:"Une culture geek sinc\xE8re. La tech comme passion, pas comme simple emploi.",descEn:"A genuine geek culture. Tech as a passion, not just a job."},{icon:"ri-compass-3-fill",title:"Une vision commune",titleEn:"A shared vision",desc:"Partager notre fa\xE7on de voir la technologie, et l'envie d'une structure \xE0 taille humaine plut\xF4t qu'un grand groupe.",descEn:"Sharing our view of technology, and wanting a human-sized company rather than a large corporation."},{icon:"ri-history-fill",title:"Le respect de l'histoire",titleEn:"Respect for our history",desc:"Comprendre d'o\xF9 vient Tyrolium, et ce que Minecraft repr\xE9sente pour nous.",descEn:"Understanding where Tyrolium comes from, and what Minecraft means to us."}]},{type:"compare",label:"La diff\xE9rence",labelEn:"The difference",title:"CV et entretien, ou TyroStage.",titleEn:"CV and interview, or TyroStage.",columns:[{name:"CV et entretien",nameEn:"CV and interview"},{name:"TyroStage",nameEn:"TyroStage",highlight:!0}],rows:[{label:"Observation sur plusieurs semaines",labelEn:"Observation over several weeks",values:[!1,!0]},{label:"Comp\xE9tences vues en situation r\xE9elle",labelEn:"Skills seen in real situations",values:[!1,!0]},{label:"Comportement sous pression",labelEn:"Behaviour under pressure",values:[!1,!0]},{label:"Travail en \xE9quipe observ\xE9",labelEn:"Teamwork observed",values:[!1,!0]},{label:"Accessible sans dipl\xF4me prestigieux",labelEn:"Open without a prestigious degree",values:[!1,!0]}]},{type:"stats",label:"Les saisons",labelEn:"The seasons",title:"Six saisons, deux \xE9coles.",titleEn:"Six seasons, two schools.",items:[{value:"S1",title:"3 stagiaires \xB7 Human Booster",titleEn:"3 interns \xB7 Human Booster"},{value:"S2",title:"4 stagiaires \xB7 Human Booster",titleEn:"4 interns \xB7 Human Booster"},{value:"S3",title:"1 stagiaire \xB7 Human Booster",titleEn:"1 intern \xB7 Human Booster"},{value:"S4",title:"3 stagiaires \xB7 Human Booster",titleEn:"3 interns \xB7 Human Booster"},{value:"S5",title:"5 stagiaires \xB7 Human Booster",titleEn:"5 interns \xB7 Human Booster"},{value:"S6",title:"4 stagiaires \xB7 IPSSI",titleEn:"4 interns \xB7 IPSSI"}],note:"19 stagiaires au total : une personne a fait deux saisons, en S3 puis en S5.",noteEn:"19 interns in total: one person did two seasons, S3 then S5."},{type:"features",label:"Et apr\xE8s",labelEn:"What came next",title:"O\xF9 ils en sont aujourd'hui.",titleEn:"Where they are today.",paragraphs:["Recruter n'est pas le seul r\xE9sultat. Chaque saison forme 3 \xE0 5 personnes et leur permet de valider leur dipl\xF4me, qu'elles restent chez nous ou non."],paragraphsEn:["Hiring is not the only outcome. Each season trains 3 to 5 people and lets them complete their degree, whether they stay with us or not."],items:[{icon:"ri-code-s-slash-fill",title:"Kevin \xB7 Saison 2",titleEn:"Kevin \xB7 Season 2",desc:"D\xE9veloppeur web et Minecraft chez Tyrolium de 2023 \xE0 2024. Et, au fil des ann\xE9es, un ami.",descEn:"Web and Minecraft developer at Tyrolium from 2023 to 2024. And, over the years, a friend."},{icon:"ri-gamepad-fill",title:"Mathys \xB7 Saison 6",titleEn:"Mathys \xB7 Season 6",desc:"R\xE9alisateur de Rhodotales, le jeu de TyroCiel. Il a fond\xE9 son propre studio, partenaire de TyroCiel.",descEn:"Director of Rhodotales, TyroCiel's game. He founded his own studio, a TyroCiel partner."},{icon:"ri-rocket-2-fill",title:"Ad\xE8le \xB7 Saison 5",titleEn:"Ad\xE8le \xB7 Season 5",desc:"Freelance. Nous lui avons transmis tout ce que nous savons, puis accompagn\xE9e dans le lancement de son activit\xE9.",descEn:"Freelancer. We passed on everything we know, then supported her in launching her business."},{icon:"ri-building-4-fill",title:"Marilyne \xB7 Saison 1",titleEn:"Marilyne \xB7 Season 1",desc:"Partie rejoindre un grand groupe du conseil num\xE9rique, avec une lettre de recommandation de Tyrolium.",descEn:"Went on to join a major digital consulting group, with a recommendation letter from Tyrolium."}]},{type:"gallery",label:"En images",labelEn:"In pictures",title:"Les saisons, dans nos locaux et ailleurs.",titleEn:"The seasons, at our offices and beyond.",photos:[{src:"assets/etudes/tyrostage/groupe-s1-s2-cafe.jpg",caption:"Saisons 1 et 2, au caf\xE9",captionEn:"Seasons 1 and 2, at the caf\xE9"},{src:"assets/etudes/tyrostage/groupe-s2-s3-locaux-1.jpg",caption:"Saisons 2 et 3, dans nos locaux",captionEn:"Seasons 2 and 3, at our offices"},{src:"assets/etudes/tyrostage/groupe-s2-s3-locaux-2.jpg",caption:"Saisons 2 et 3, dans nos locaux",captionEn:"Seasons 2 and 3, at our offices"},{src:"assets/etudes/tyrostage/groupe-s5-locaux-1.jpg",caption:"Saison 5, dans nos locaux",captionEn:"Season 5, at our offices"},{src:"assets/etudes/tyrostage/groupe-s5-locaux-2.jpg",caption:"Saison 5, dans nos locaux",captionEn:"Season 5, at our offices"},{src:"assets/etudes/tyrostage/groupe-s5-locaux-3.jpg",caption:"Saison 5, dans nos locaux",captionEn:"Season 5, at our offices"},{src:"assets/etudes/tyrostage/groupe-s6-cafe.jpg",caption:"Saison 6, au caf\xE9",captionEn:"Season 6, at the caf\xE9"}]},{type:"voices",label:"Leurs voix",labelEn:"Their voices",title:"Ce sont eux qui en parlent le mieux.",titleEn:"They tell it best.",paragraphs:["Des stagiaires recrut\xE9s, d'autres partis ailleurs, et m\xEAme des \xE9tudiants que nous n'avons pas recrut\xE9s : tous racontent leur exp\xE9rience."],paragraphsEn:["Interns we hired, others who moved on, and even students we did not hire: they all share their experience."],voices:[{name:"Kevin Muziak",role:"D\xE9veloppeur chez Tyrolium de 2023 \xE0 2024",roleEn:"Developer at Tyrolium, 2023\u20132024",tag:"TyroStage S2 \xB7 Human Booster",tagEn:"TyroStage S2 \xB7 Human Booster",recruited:!0,photo:"assets/etudes/tyrostage/kevin-muziak.jpg",audio:"assets/etudes/tyrostage/kevin-muziak.m4a",quote:"Ensemble, m\xEAme avec peu ou pas d'exp\xE9rience, on a pu faire des choses tr\xE8s \xE9labor\xE9es, qui avaient du sens.",quoteEn:"Together, even with little or no experience, we were able to build highly elaborate things that made sense.",transcript:"Bonjour, je suis ici pour t\xE9moigner de mes activit\xE9s pass\xE9es avec Maxime Tournier au sein de l'entreprise Tyrolium. J'ai \xE9t\xE9 recrut\xE9 pour mon stage au sein de cette entreprise. Nous avons fait, entre autres, des sites web, et travaill\xE9 sur plusieurs projets internes, en apprenant diverses technologies et diverses mani\xE8res de fonctionner. Nous avons d\xE9couvert des outils internes cr\xE9\xE9s par l'entreprise, par Maxime Tournier lui-m\xEAme. Maxime a su faire preuve de patience, de p\xE9dagogie, et surtout nous montrer toutes ces petites techniques qu'il a apprises au fil de ses ann\xE9es d'exp\xE9rience, dans le code comme ailleurs. Nous avons \xE9t\xE9 capables d'\xEAtre productifs alors que nous n'avions que quelques mois de d\xE9veloppement web derri\xE8re nous, parfois seuls, parfois en petit ou moyen groupe. Nous avons vu qu'ensemble, m\xEAme avec peu ou pas d'exp\xE9rience, on pouvait faire des choses tr\xE8s \xE9labor\xE9es, qui avaient du sens, et qui nous valorisaient vraiment une fois nos t\xE2ches quotidiennes, hebdomadaires et mensuelles termin\xE9es. C'\xE9tait une tr\xE8s belle exp\xE9rience, qui m'a beaucoup appris sur moi et sur le m\xE9tier. Maxime est quelqu'un que je suis content d'avoir rencontr\xE9, et qui a beaucoup \xE0 apprendre et \xE0 faire d\xE9couvrir aux autres.",transcriptEn:"Hello, I'm here to talk about my past work with Maxime Tournier at Tyrolium. I was recruited for my internship at the company. Among other things, we built websites and worked on several internal projects, learning various technologies and ways of working. We discovered internal tools created by the company, by Maxime Tournier himself. Maxime showed patience and teaching skills, and above all shared all the little techniques he has picked up over his years of experience, in code and beyond. We managed to be productive with only a few months of web development behind us, sometimes alone, sometimes in small or medium groups. We saw that together, even with little or no experience, we could build highly elaborate things that made sense, and that truly rewarded us once our daily, weekly and monthly tasks were done. It was a wonderful experience that taught me a lot about myself and the job. Maxime is someone I'm glad I met, and who has a lot to teach and share with others."},{name:"Bastien Thiebaut",role:"D\xE9veloppeur chez Tyrolium de 2024 \xE0 2025",roleEn:"Developer at Tyrolium, 2024\u20132025",tag:"TyroStage S5 \xB7 Human Booster",tagEn:"TyroStage S5 \xB7 Human Booster",recruited:!0,photo:"assets/etudes/tyrostage/bastien-thiebaut.jpg",audio:"assets/etudes/tyrostage/bastien-thiebaut.m4a",quote:"Maxime \xE9tait toujours disponible pour nous aider. On n'\xE9tait jamais d\xE9laiss\xE9s.",quoteEn:"Maxime was always available to help us. We were never left on our own.",transcript:"Je m'appelle Bastien Thiebaut, j'ai 26 ans, je suis d\xE9veloppeur web et ancien stagiaire de Tyrolium. J'ai rencontr\xE9 Maxime pendant ma formation de d\xE9veloppeur web : c'\xE9tait tout simplement l'un de mes formateurs. Le courant est tout de suite pass\xE9. Pour valider ma formation, je devais trouver un stage en entreprise ; j'ai demand\xE9 \xE0 Maxime s'il cherchait un stagiaire, et c'\xE9tait le cas. C'est comme \xE7a que j'ai int\xE9gr\xE9 Tyrolium, pour quatre mois. La collaboration \xE9tait vraiment tr\xE8s agr\xE9able : toujours dans la bonne humeur, tout en gardant un vrai professionnalisme. Ce qui a rendu cette exp\xE9rience si agr\xE9able, c'est que Maxime \xE9tait toujours disponible pour nous aider. On n'\xE9tait jamais d\xE9laiss\xE9s. On travaillait principalement sur Discord et, d\xE8s qu'on avait un probl\xE8me, on arrivait tr\xE8s vite \xE0 le joindre et \xE0 trouver une solution, que ce soit pour une consigne mal comprise ou un bug dans le code. Nous avons travaill\xE9 sur un projet assez gros pour des d\xE9veloppeurs d\xE9butants : Gamenium, un projet interne. M\xEAme si c'\xE9tait son projet et qu'il avait d\xE9j\xE0 beaucoup d'id\xE9es, il restait tr\xE8s ouvert au d\xE9bat et \xE0 l'\xE9coute de nos propositions. Il tenait aussi \xE0 ce qu'on obtienne notre dipl\xF4me : il nous a accord\xE9 beaucoup de temps en fin de stage, et je n'aurais peut-\xEAtre pas \xE9t\xE9 aussi bien pr\xE9par\xE9 \xE0 l'examen final sans lui. Merci \xE0 lui. Maxime est avant tout un passionn\xE9, \xE7a se ressent quand il explique les choses. Il est \xE9norm\xE9ment \xE0 l'\xE9coute, prend toujours en compte les avis avant de se prononcer, et ne compte pas ses heures. Je le remercie pour cette exp\xE9rience \xE0 la fois professionnelle et tr\xE8s humaine.",transcriptEn:"My name is Bastien Thiebaut, I'm 26, a web developer and a former Tyrolium intern. I met Maxime during my web developer training: he was simply one of my trainers. We clicked straight away. To complete my training, I needed to find a company internship; I asked Maxime if he was looking for an intern, and he was. That's how I joined Tyrolium, for four months. Working together was really enjoyable: always in a good mood, while staying genuinely professional. What made this experience so good was that Maxime was always available to help us. We were never left on our own. We mostly worked on Discord and, whenever we had a problem, we could reach him quickly and find a solution, whether it was a misunderstood instruction or a bug in the code. We worked on a fairly big project for beginner developers: Gamenium, an internal project. Even though it was his project and he already had lots of ideas, he stayed very open to debate and listened to our suggestions. He also cared about us getting our degree: he gave us a lot of time at the end of the internship, and I might not have been as well prepared for my final exam without him. Thanks to him. Maxime is above all passionate, and you can feel it when he explains things. He listens a lot, always takes opinions into account before deciding, and never counts his hours. I thank him for an experience that was both professional and deeply human."},{name:"Ad\xE8le Jausons",role:"D\xE9veloppeuse chez Tyrolium de 2024 \xE0 2025, aujourd'hui freelance",roleEn:"Developer at Tyrolium, 2024\u20132025, now a freelancer",tag:"TyroStage S5 \xB7 Human Booster",tagEn:"TyroStage S5 \xB7 Human Booster",recruited:!0,photo:"assets/etudes/tyrostage/adele-jausons.jpg",audio:"assets/etudes/tyrostage/adele-jausons.m4a",quote:"On ne m'a pas juste donn\xE9 des petites t\xE2ches \xE0 faire dans mon coin : on m'a impliqu\xE9e dans un projet, et accompagn\xE9e.",quoteEn:"I wasn't just handed small tasks to do on my own: I was involved in a project, and supported.",transcript:"Salut, moi c'est Ad\xE8le, je suis d\xE9veloppeuse web et je vais vous parler de mon stage chez Tyrolium. Quand j'ai commenc\xE9, l'objectif \xE9tait de passer de la th\xE9orie \xE0 la pratique. J'ai travaill\xE9 sur trois projets : un site vitrine, une application web complexe et ambitieuse mais passionnante, et un outil interne \xE0 Tyrolium. Ce que j'ai beaucoup aim\xE9, c'est qu'on ne m'a pas juste donn\xE9 des petites t\xE2ches \xE0 faire dans mon coin, du genre \xAB fais-le et reviens quand tu as fini \xBB. On m'a vraiment impliqu\xE9e dans un projet et accompagn\xE9e : on m'a laiss\xE9 de l'autonomie, tout en \xE9tant toujours pr\xE9sent si besoin. J'ai principalement travaill\xE9 \xE0 distance, ce qui aurait pu compliquer les choses, mais Maxime \xE9tait toujours l\xE0 pour r\xE9pondre aux questions. Il est aussi tr\xE8s rod\xE9 c\xF4t\xE9 communication et outils, y compris les outils clients pour montrer o\xF9 en est le projet. C'\xE9tait super pratique. J'ai vraiment ador\xE9 : un stage structur\xE9, accompagn\xE9, organis\xE9. Et pourtant nous \xE9tions pas mal de stagiaires, et Maxime s'occupait de tout seul. Techniquement, j'ai \xE9norm\xE9ment progress\xE9 : lire du code, le comprendre, le modifier ; j'ai d\xE9couvert de nouvelles technologies et je me suis beaucoup am\xE9lior\xE9e sur celles que je connaissais. J'ai suivi des projets de A \xE0 Z, et repris des projets existants. L'ambiance \xE9tait hyper sympa. Maxime est avenant, bienveillant, \xE0 l'\xE9coute, tr\xE8s professionnel, et il veut toujours comprendre : le client, le probl\xE8me, ce qui se passe. Je trouve \xE7a essentiel dans ce m\xE9tier, et c'est ce qui fait que Tyrolium vaut le coup. Je recommande \xE0 100 %, que ce soit pour un stage, un travail, un site ou autre. Allez-y les yeux ferm\xE9s : moi, je ne regrette pas du tout.",transcriptEn:`Hi, I'm Ad\xE8le, a web developer, and I'm going to talk about my internship at Tyrolium. When I started, the goal was to move from theory to practice. I worked on three projects: a showcase website, a complex, ambitious but fascinating web application, and an internal Tyrolium tool. What I really liked was that I wasn't just handed small tasks to do on my own, the "do it and come back when you're done" kind. I was truly involved in a project and supported: given autonomy, with someone always there if needed. I mostly worked remotely, which could have made things harder, but Maxime was always there to answer questions. He's also very well organised with communication and tools, including client tools to show how a project is progressing. It was really convenient. I absolutely loved it: a structured, well-supported, organised internship. And yet there were quite a few of us interns, and Maxime handled everything on his own. Technically, I made huge progress: reading code, understanding it, changing it; I discovered new technologies and got much better at the ones I knew. I followed projects from A to Z, and took over existing ones. The atmosphere was really friendly. Maxime is approachable, kind, attentive, very professional, and he always wants to understand: the client, the problem, what's going on. I think that's essential in this job, and it's what makes Tyrolium worth it. I recommend it 100%, whether for an internship, a job, a website or anything else. Go for it with your eyes closed: I don't regret it one bit.`},{name:"Maxence Emery",role:"D\xE9veloppeur et int\xE9grateur, apprenant en formation",roleEn:"Developer and integrator, former trainee",tag:"Human Booster",tagEn:"Human Booster",recruited:!1,photo:"assets/etudes/tyrostage/maxence-emery.jpg",audio:"assets/etudes/tyrostage/maxence-emery.m4a",quote:"Si ma pr\xE9sentation \xE9tait bonne, c'est notamment gr\xE2ce \xE0 lui et \xE0 son \xE9coute attentive.",quoteEn:"If my presentation went well, it was largely thanks to him and how closely he listened.",transcript:"Je m'appelle Maxence Emery, je suis int\xE9grateur WordPress. J'ai obtenu en f\xE9vrier 2025 mon dipl\xF4me de d\xE9veloppeur web et web mobile. J'ai rencontr\xE9 Maxime Tournier pendant mes \xE9tudes : c'\xE9tait l'un de mes professeurs. J'ai tout de suite \xE9t\xE9 s\xE9duit par son approche : toujours extr\xEAmement disponible et professionnel, il nous parlait de ses exp\xE9riences et nous aidait chaque fois qu'il le pouvait. Il m'a \xE9t\xE9 d'une aide pr\xE9cieuse en fin d'ann\xE9e. Je devais pr\xE9senter mon dossier projet devant un jury, et il m'a permis de faire une sorte d'examen blanc avec lui, avec beaucoup de conseils et d'axes d'am\xE9lioration. J'ai \xE9norm\xE9ment travaill\xE9 pour obtenir ce dipl\xF4me, mais si ma pr\xE9sentation \xE9tait bonne, c'est notamment gr\xE2ce \xE0 lui et \xE0 son \xE9coute attentive. Je devais aussi d\xE9ployer un site sur un serveur, ce qui \xE9tait particuli\xE8rement compliqu\xE9 avec les technologies impos\xE9es. Sans Maxime pour m'aiguiller, je ne suis pas s\xFBr que j'aurais pu r\xE9aliser ce d\xE9ploiement dans de bonnes conditions. Il a toujours \xE9t\xE9 force de proposition. C'est un professeur d'une grande maturit\xE9 malgr\xE9 son jeune \xE2ge, et je suis tr\xE8s heureux de l'avoir eu.",transcriptEn:"My name is Maxence Emery, I'm a WordPress integrator. In February 2025 I earned my web and mobile web developer diploma. I met Maxime Tournier during my studies: he was one of my teachers. I was immediately won over by his approach: always extremely available and professional, he shared his experience and helped us whenever he could. He was a huge help at the end of the year. I had to present my project file to a jury, and he let me do a kind of mock exam with him, with lots of advice and areas for improvement. I worked extremely hard for this diploma, but if my presentation went well, it was largely thanks to him and how closely he listened. I also had to deploy a website on a server, which was particularly tricky with the technologies we were required to use. Without Maxime guiding me, I'm not sure I could have done that deployment properly. He always came up with ideas. He's a teacher with great maturity despite his young age, and I'm very glad I had him."}]},{type:"features",label:"Nos r\xE8gles",labelEn:"Our rules",title:"Former d'abord. Recruter ensuite.",titleEn:"Teach first. Hire second.",paragraphs:["\xCAtre \xE0 la fois formateur et recruteur impose des r\xE8gles claires. Les voici, et nous les appliquons \xE0 chaque intervention."],paragraphsEn:["Being both trainer and recruiter requires clear rules. Here they are, and we apply them at every course."],items:[{icon:"ri-megaphone-fill",title:"Transparence d\xE8s le premier jour",titleEn:"Transparency from day one",desc:"Les \xE9tudiants savent d\xE8s le d\xE9but que Tyrolium recrute ses stagiaires ainsi.",descEn:"Students know from the start that this is how Tyrolium recruits its interns."},{icon:"ri-scales-3-fill",title:"Des notes ind\xE9pendantes",titleEn:"Independent grades",desc:"Personne n'est not\xE9 par pr\xE9f\xE9rence. Le recrutement ne change rien \xE0 l'\xE9valuation.",descEn:"No one is graded by preference. Recruitment has no bearing on assessment."},{icon:"ri-time-fill",title:"Aucune proposition pendant le cours",titleEn:"No offers during the course",desc:"Les propositions arrivent toujours apr\xE8s l'intervention, et nous refusons toute demande pendant.",descEn:"Offers always come after the course, and we decline any request during it."},{icon:"ri-hand-heart-fill",title:"Aider aussi ceux qu'on ne recrute pas",titleEn:"Helping those we do not hire",desc:"Conseils, mentorat, recommandations : la formation profite \xE0 toute la promotion.",descEn:"Advice, mentoring, recommendations: the training benefits the whole class."}]},{type:"features",label:"Gagnant-gagnant",labelEn:"Win-win",title:"Trois gagnants.",titleEn:"Three winners.",items:[{icon:"ri-graduation-cap-fill",title:"L'\xE9tudiant",titleEn:"The student",desc:"Une formation concr\xE8te, un stage qui valide son dipl\xF4me, et une porte ouverte sur la suite.",descEn:"Hands-on training, an internship that completes their degree, and an open door for what comes next."},{icon:"ri-school-fill",title:"L'\xE9cole",titleEn:"The school",desc:"Un formateur issu du terrain, et des d\xE9bouch\xE9s r\xE9els pour ses \xE9tudiants.",descEn:"A trainer from the field, and real opportunities for its students."},{icon:"ri-team-fill",title:"Tyrolium",titleEn:"Tyrolium",desc:"Des talents passionn\xE9s, qui connaissent d\xE9j\xE0 notre exigence et notre culture.",descEn:"Passionate talent who already know our standards and our culture."}]},{type:"features",label:"Les le\xE7ons",labelEn:"The lessons",title:"Ce que nous en retenons.",titleEn:"What we take away.",items:[{icon:"ri-search-eye-fill",title:"Observer vaut mieux que questionner",titleEn:"Watching beats questioning",desc:"Des semaines de travail r\xE9el r\xE9v\xE8lent plus qu'un entretien parfaitement pr\xE9par\xE9.",descEn:"Weeks of real work reveal more than a perfectly rehearsed interview."},{icon:"ri-seedling-fill",title:"La technique s'apprend, pas la soif",titleEn:"Skills can be taught, hunger cannot",desc:"Recruter la motivation et former ensuite, c'est notre pari, et il fonctionne.",descEn:"Hiring for motivation and training afterwards is our bet, and it works."},{icon:"ri-group-fill",title:"Un groupe soud\xE9 apprend plus vite",titleEn:"A close group learns faster",desc:"Accueillir des personnes qui s'appr\xE9cient d\xE9j\xE0 cr\xE9e une dynamique imm\xE9diate.",descEn:"Welcoming people who already get along creates instant momentum."}]}],cta:{title:"Vous \xEAtes une \xE9cole ?",titleEn:"Are you a school?",content:"Faites intervenir un formateur issu du terrain, et offrez \xE0 vos \xE9tudiants des projets r\xE9els et des d\xE9bouch\xE9s concrets.",contentEn:"Bring in a trainer from the field, and give your students real projects and concrete opportunities.",btn:"Proposer une intervention",btnEn:"Invite us to teach",btnIcon:"ri-graduation-cap-line",routerLink:"/contact"}},{slug:"timeclaw",publishedAt:"2026-10-16",brand:"TimeClaw",logo:"assets/tyrolium-ui/projects/TyroCiel-White.png",partnerLogo:"assets/etudes/timeclaw-white.png",gradient:"linear-gradient(135deg, #0000FF 0%, #BF0000 100%)",category:"Incubation \xB7 Jeu vid\xE9o",categoryEn:"Incubation \xB7 Video games",period:"De TyroStage \xE0 TimeClaw",periodEn:"From TyroStage to TimeClaw",dataAsOf:"octobre 2026",dataAsOfEn:"October 2026",title:"Il voulait son propre studio. Nous l'avons aid\xE9 \xE0 le cr\xE9er.",titleEn:"He wanted his own studio. We helped him build it.",summary:"Mathys est arriv\xE9 chez nous en stage. Il est devenu le r\xE9alisateur de Rhodotales, puis l'une des t\xEAtes pensantes de TyroCiel. Quand il a voulu cr\xE9er ses propres jeux, nous ne l'avons pas retenu : nous avons incub\xE9 son studio, TimeClaw. Et il n'a jamais quitt\xE9 Rhodotales.",summaryEn:"Mathys joined us as an intern. He became the director of Rhodotales, then one of TyroCiel's leading minds. When he wanted to make his own games, we did not hold him back: we incubated his studio, TimeClaw. And he never left Rhodotales.",headline:{value:"2",title:"studios r\xE9unis sur un m\xEAme jeu",titleEn:"studios united on one game"},heroStats:[{value:"2",title:"Studios sur un m\xEAme jeu",titleEn:"Studios on one game"},{value:"6 mois",valueEn:"6 months",title:"De stagiaire \xE0 fondateur de studio",titleEn:"From intern to studio founder"},{value:"4",title:"Piliers d'accompagnement par Tyrolium",titleEn:"Areas of support from Tyrolium"},{value:"0",title:"Investisseur ext\xE9rieur",titleEn:"Outside investors"}],facts:[{label:"Studio",labelEn:"Studio",value:"TimeClaw"},{label:"Fondateur",labelEn:"Founder",value:"Mathys Lacoque"},{label:"Arriv\xE9e chez Tyrolium",labelEn:"Joined Tyrolium",value:"Avril 2026",valueEn:"April 2026"},{label:"Fondation de TimeClaw",labelEn:"TimeClaw founded",value:"Octobre 2026",valueEn:"October 2026"},{label:"Parcours",labelEn:"Path",value:"TyroStage S6 (IPSSI) \u2192 r\xE9alisateur chez TyroCiel \u2192 fondateur de TimeClaw",valueEn:"TyroStage S6 (IPSSI) \u2192 director at TyroCiel \u2192 founder of TimeClaw"},{label:"Projet commun",labelEn:"Joint project",value:"Rhodotales, avec TyroCiel",valueEn:"Rhodotales, with TyroCiel"},{label:"Apport de Tyrolium",labelEn:"Tyrolium's support",value:"Administratif, communication, site web, incubation",valueEn:"Admin, communication, website, incubation"}],link:{label:"tyrociel.fr",url:"https://tyrociel.fr"},blocks:[{type:"text",label:"Le point de d\xE9part",labelEn:"Where it started",title:"Un stagiaire parmi quatre.",titleEn:"One intern out of four.",paragraphs:["Tout commence en janvier 2026, \xE0 l'IPSSI : notre fondateur rencontre Mathys lors de son premier cours avec sa promotion. De janvier \xE0 avril, il leur donne cours pendant environ six semaines, de 9 h \xE0 17 h, tous les jours.","En avril 2026, Mathys rejoint Tyrolium avec la saison 6 de TyroStage, aux c\xF4t\xE9s de trois autres \xE9tudiants de sa promotion. Comme toujours, nous ne l'avons pas choisi sur un CV : nous l'avons regard\xE9 travailler pendant six semaines.","D\xE9veloppeur de formation, il commence sur Rhodotales, le jeu de TyroCiel, le studio de jeu vid\xE9o du groupe. Tr\xE8s vite, il ne se contente plus de coder ce qu'on lui demande : il propose, il imagine, il tranche."],paragraphsEn:["It all starts in January 2026, at IPSSI: our founder meets Mathys during his first class with his cohort. From January to April, he teaches them for about six weeks, from 9 a.m. to 5 p.m., every day.","In April 2026, Mathys joins Tyrolium with season 6 of TyroStage, alongside three other students from his cohort. As always, we did not pick him from a CV: we watched him work for six weeks.","A developer by training, he starts on Rhodotales, the game of TyroCiel, the group's video game studio. Very quickly, he no longer just codes what he is asked: he suggests, imagines, decides."],linkLabel:"Lire l'\xE9tude de cas TyroStage",linkLabelEn:"Read the TyroStage case study",linkRouter:"/etudes-de-cas/tyrostage"},{type:"steps",label:"Le parcours",labelEn:"The path",title:"De stagiaire \xE0 t\xEAte pensante.",titleEn:"From intern to leading mind.",items:[{title:"Avril 2026 \xB7 Stagiaire sur Rhodotales",titleEn:"April 2026 \xB7 Intern on Rhodotales",desc:"Il rejoint l'\xE9quipe du jeu pendant son stage, et apprend sur un vrai projet de studio.",descEn:"He joins the game team during his internship and learns on a real studio project."},{title:"Ao\xFBt 2026 \xB7 R\xE9alisateur de Rhodotales",titleEn:"August 2026 \xB7 Director of Rhodotales",desc:"On lui laisse de la place, il la prend : il devient le r\xE9alisateur du jeu et en porte la vision.",descEn:"We give him room, and he takes it: he becomes the director of the game and carries its vision."},{title:"Ao\xFBt \u2013 octobre 2026 \xB7 Une t\xEAte pensante de TyroCiel",titleEn:"August \u2013 October 2026 \xB7 A leading mind at TyroCiel",desc:"Au-del\xE0 de Rhodotales, il p\xE8se sur la direction cr\xE9ative et la marque de toute une filiale. Et il a envie de cr\xE9er aussi ses propres petits jeux, avec sa propre identit\xE9.",descEn:"Beyond Rhodotales, he shapes the creative direction and brand of an entire subsidiary. And he also wants to make his own small games, with his own identity."},{title:"Octobre 2026 \xB7 La fondation de TimeClaw",titleEn:"October 2026 \xB7 Founding TimeClaw",desc:"Plut\xF4t que de le perdre, nous incubons son studio. TimeClaw devient partenaire de TyroCiel.",descEn:"Rather than lose him, we incubate his studio. TimeClaw becomes a TyroCiel partner."}]},{type:"story",label:"La discussion",labelEn:"The conversation",title:"\xAB Ton talent est trop important. \xBB",titleEn:'"Your talent matters too much."',paragraphs:["Quand Mathys m'a dit qu'il voulait cr\xE9er ses propres jeux, je lui ai r\xE9pondu franchement : \xE7a ne me d\xE9range pas. Qu'il veuille son ind\xE9pendance, je le respecte.","Mais je lui ai dit aussi ce que je pensais : ton talent est trop important. Je t'ai laiss\xE9 de la place, et tu l'as prise. Tu n'es plus un simple d\xE9veloppeur de Rhodotales : tu es devenu l'une des t\xEAtes pensantes de toute une filiale de Tyrolium.","Le perdre aurait \xE9t\xE9 une erreur, le retenir aussi. Apr\xE8s plusieurs discussions, nous sommes tomb\xE9s d'accord : il cr\xE9e son studio, nous l'aidons \xE0 le monter, et il reste avec nous sur Rhodotales."],paragraphsEn:["When Mathys told me he wanted to make his own games, I answered honestly: I do not mind. If he wants his independence, I respect that.","But I also told him what I thought: your talent matters too much. I gave you room, and you took it. You are no longer just a developer on Rhodotales: you have become one of the leading minds of an entire Tyrolium subsidiary.","Losing him would have been a mistake; so would holding him back. After several conversations, we agreed: he founds his studio, we help him set it up, and he stays with us on Rhodotales."],author:"Maxime Tournier",authorRole:"PDG & Fondateur de Tyrolium",authorRoleEn:"CEO & Founder of Tyrolium"},{type:"compare",label:"Le choix",labelEn:"The choice",title:"Trois fa\xE7ons de r\xE9agir face \xE0 un talent qui veut cr\xE9er sa bo\xEEte.",titleEn:"Three ways to react when a talent wants to start their own company.",columns:[{name:"Le retenir en interne",nameEn:"Hold him back in-house"},{name:"Le laisser partir seul",nameEn:"Let him leave alone"},{name:"Incubation TimeClaw \xD7 TyroCiel",nameEn:"TimeClaw \xD7 TyroCiel incubation",highlight:!0}],rows:[{label:"Libert\xE9 de cr\xE9er ses propres jeux et sa marque",labelEn:"Freedom to create his own games and brand",values:[!1,!0,!0]},{label:"Rhodotales conserve son r\xE9alisateur",labelEn:"Rhodotales keeps its director",values:[!0,!1,!0]},{label:"Accompagnement administratif, site web et communication",labelEn:"Admin, website and communication support",values:[!0,!1,!0]},{label:"Deux communaut\xE9s r\xE9unies autour du m\xEAme jeu",labelEn:"Two communities united around the same game",values:[!1,!1,!0]}]},{type:"features",label:"L'accord",labelEn:"The deal",title:"Ce que Tyrolium apporte \xE0 TimeClaw.",titleEn:"What Tyrolium brings to TimeClaw.",paragraphs:["Cr\xE9er un studio, ce n'est pas seulement faire des jeux. Tout ce qui n'est pas le jeu, nous le prenons en charge, pour que Mathys puisse se concentrer sur la cr\xE9ation."],paragraphsEn:["Running a studio is not just making games. We take care of everything that is not the game, so Mathys can focus on creating."],items:[{icon:"ri-file-list-3-fill",title:"L'administratif",titleEn:"The paperwork",desc:"Cr\xE9ation de la structure et d\xE9marches : nous l'aidons \xE0 monter son studio dans les r\xE8gles.",descEn:"Setting up the company and the formalities: we help him found his studio properly."},{icon:"ri-megaphone-fill",title:"La communication",titleEn:"Communication",desc:"Nous portons la communication de TimeClaw, avec les m\xEAmes outils que pour nos filiales.",descEn:"We run TimeClaw's communication, with the same tools we use for our subsidiaries."},{icon:"ri-window-fill",title:"Le site web",titleEn:"The website",desc:"Son site est con\xE7u et h\xE9berg\xE9 par nos \xE9quipes.",descEn:"His website is designed and hosted by our teams."},{icon:"ri-rocket-2-fill",title:"L'incubation",titleEn:"Incubation",desc:"Conseils, mentorat et l'appui de tout un groupe pour faire grandir le studio.",descEn:"Advice, mentoring and the backing of a whole group to grow the studio."}]},{type:"features",label:"En \xE9change",labelEn:"In return",title:"Ce que TimeClaw apporte \xE0 TyroCiel.",titleEn:"What TimeClaw brings to TyroCiel.",items:[{icon:"ri-movie-2-fill",title:"Rhodotales garde son r\xE9alisateur",titleEn:"Rhodotales keeps its director",desc:"Mathys reste aux commandes du jeu, d\xE9sormais \xE0 la t\xEAte de son propre studio.",descEn:"Mathys stays at the helm of the game, now heading his own studio."},{icon:"ri-lightbulb-flash-fill",title:"Un pied dans tous les projets",titleEn:"A foot in every project",desc:"Il garde un r\xF4le sur l'ensemble des projets de TyroCiel, pas seulement sur Rhodotales.",descEn:"He keeps a role across all of TyroCiel's projects, not just Rhodotales."},{icon:"ri-gamepad-fill",title:"Ses propres jeux en parall\xE8le",titleEn:"His own games alongside",desc:"TimeClaw d\xE9veloppe ses projets librement, sans que TyroCiel perde son talent.",descEn:"TimeClaw builds its own projects freely, without TyroCiel losing his talent."}]},{type:"testimonial",quote:"En arrivant en stage, je voulais juste gagner de l'exp\xE9rience en d\xE9veloppement de jeux vid\xE9o. Tr\xE8s vite, on m'a confi\xE9 la r\xE9alisation de Rhodotales. Je ne pensais pas \xEAtre \xE0 la hauteur, et je me suis prouv\xE9 le contraire. Quand j'ai voulu cr\xE9er mon studio, Tyrolium ne m'a pas retenu : ils m'ont encourag\xE9 \xE0 me lancer. Aujourd'hui, TimeClaw est une entit\xE9 \xE0 part enti\xE8re : j'aide TyroCiel \xE0 d\xE9velopper Rhodotales, tout en menant mes propres projets.",quoteEn:"When I started my internship, I just wanted to gain experience in video game development. Very quickly, I was given the direction of Rhodotales. I did not think I was up to it, and I proved myself wrong. When I wanted to start my own studio, Tyrolium did not hold me back: they encouraged me to go for it. Today, TimeClaw is an entity in its own right: I help TyroCiel develop Rhodotales, while running my own projects.",author:"Mathys Lacoque",authorRole:"Fondateur de TimeClaw \xB7 R\xE9alisateur de Rhodotales",authorRoleEn:"Founder of TimeClaw \xB7 Director of Rhodotales",photo:"assets/teams/Mathys_Lacoque.jpg"},{type:"alliance",label:"Co-d\xE9veloppement",labelEn:"Co-development",title:"Deux studios, un jeu, une m\xEAme force de frappe.",titleEn:"Two studios, one game, the same reach.",paragraphs:["Rhodotales est un jeu de plateforme HD-2D dans un monde m\xE9di\xE9val fantastique. Sa m\xE9canique signature : naviguer entre 3 plans distincts. Le partenariat unit la structure de TyroCiel et la direction cr\xE9ative de TimeClaw.","Les outils de communication de Tyrolium, qui portent tout TyroCiel, sont partag\xE9s pour Rhodotales : le jeu est port\xE9 \xE0 la fois sur les profils de TyroCiel et sur ceux de TimeClaw."],paragraphsEn:["Rhodotales is an HD-2D platformer set in a medieval fantasy world. Its signature mechanic: moving between 3 distinct planes. The partnership unites TyroCiel's structure and TimeClaw's creative direction.","Tyrolium's communication tools, which power all of TyroCiel, are shared for Rhodotales: the game is promoted on both TyroCiel's and TimeClaw's profiles."],alliance:{leftName:"TyroCiel",leftGroup:"Tyrolium",leftRole:"Studio de jeu vid\xE9o du groupe \xB7 Production & Financement",leftRoleEn:"Group video game studio \xB7 Production & Funding",leftLogo:"assets/tyrolium-ui/projects/TyroCiel.png",rightName:"TimeClaw",rightGroup:"Studio partenaire incub\xE9",rightRole:"Studio ind\xE9pendant de Mathys Lacoque \xB7 R\xE9alisation & Cr\xE9ation",rightRoleEn:"Mathys Lacoque's indie studio \xB7 Direction & Creation",rightLogo:"assets/partners/timeclaw.png",projectTitle:"Rhodotales",projectTag:"Plateforme HD-2D \xB7 M\xE9di\xE9val fantastique \xB7 3 plans de profondeur",projectTagEn:"HD-2D Platformer \xB7 Medieval fantasy \xB7 3 depth planes",projectDesc:"Deux vitrines, une m\xEAme bo\xEEte \xE0 outils de communication, et un d\xE9veloppement 100 % financ\xE9 en fonds propres par le groupe.",projectDescEn:"Two showcases, the same communication toolkit, and development 100% self-funded by the group.",pillars:[{icon:"ri-share-forward-fill",label:"Deux vitrines pour un jeu",labelEn:"Two showcases for one game"},{icon:"ri-tools-fill",label:"Outils de com partag\xE9s",labelEn:"Shared communication tools"},{icon:"ri-hand-coin-fill",label:"100 % financ\xE9 en fonds propres",labelEn:"100% self-funded"}]}},{type:"features",label:"Gagnant-gagnant",labelEn:"Win-win",title:"Trois gagnants.",titleEn:"Three winners.",items:[{icon:"ri-user-star-fill",title:"Mathys",titleEn:"Mathys",desc:"Son ind\xE9pendance et ses propres jeux, sans repartir de z\xE9ro ni porter seul l'administratif et la communication.",descEn:"His independence and his own games, without starting from scratch or carrying the paperwork and communication alone."},{icon:"ri-gamepad-fill",title:"TyroCiel",titleEn:"TyroCiel",desc:"Le studio garde son r\xE9alisateur et l'une de ses t\xEAtes pensantes.",descEn:"The studio keeps its director and one of its leading minds."},{icon:"ri-building-4-fill",title:"Tyrolium",titleEn:"Tyrolium",desc:"Un studio partenaire de plus dans l'\xE9cosyst\xE8me, n\xE9 d'un talent que nous avons form\xE9.",descEn:"One more partner studio in the ecosystem, born from a talent we trained."}]},{type:"features",label:"Les le\xE7ons",labelEn:"The lessons",title:"Ce que nous en retenons.",titleEn:"What we take away.",items:[{icon:"ri-seedling-fill",title:"Laisser de la place r\xE9v\xE8le les talents",titleEn:"Giving room reveals talent",desc:"Mathys n'\xE9tait pas recrut\xE9 pour diriger un jeu. Il l'est devenu parce qu'on l'a laiss\xE9 faire.",descEn:"Mathys was not hired to direct a game. He became its director because we let him."},{icon:"ri-door-open-fill",title:"Retenir n'est pas enfermer",titleEn:"Keeping is not caging",desc:"Un talent qui veut son ind\xE9pendance la prendra. Autant l'aider \xE0 la construire avec nous.",descEn:"A talent who wants independence will take it. Better to help them build it with us."},{icon:"ri-shake-hands-fill",title:"Un d\xE9part peut devenir un partenariat",titleEn:"A departure can become a partnership",desc:"Le lien ne se coupe pas : il change de forme, et il renforce les deux c\xF4t\xE9s.",descEn:"The bond is not cut: it changes shape, and it strengthens both sides."}],linkLabel:"D\xE9couvrir notre vision",linkLabelEn:"Discover our vision",linkRouter:"/vision"}],cta:{title:"Vous voulez cr\xE9er votre studio ?",titleEn:"Want to start your own studio?",content:"L'incubateur Tyrolium accompagne les porteurs de projet, de l'id\xE9e jusqu'\xE0 l'entreprise.",contentEn:"The Tyrolium incubator supports project founders, from the idea to the company.",btn:"D\xE9couvrir l'incubateur",btnEn:"Discover the incubator",btnIcon:"ri-rocket-2-line",routerLink:"/prestation/incubateur"}},{slug:"solidserv",publishedAt:"2026-10-16",brand:"SolidServ",logo:"assets/tyrolium-ui/projects/SolidServ-White.png",partnerCombo:{logo:"assets/tyrolium-ui/projects/SolidServ-White.png",group:"Tyrolium",name:"SolidServ"},gradient:"linear-gradient(135deg, #0000FF 0%, #BF0000 100%)",category:"H\xE9bergement \xB7 Infrastructure",categoryEn:"Hosting \xB7 Infrastructure",period:"2022 \u2013 aujourd'hui",periodEn:"2022 \u2013 today",dataAsOf:"octobre 2026",dataAsOfEn:"October 2026",title:"L'h\xE9bergeur n\xE9 dans la gal\xE8re, devenu le moteur du groupe",titleEn:"The host born in hard times that became the group's engine",summary:"SolidServ est n\xE9 en 2022 d'une id\xE9e de Pierre-Louis, avec des serveurs achet\xE9s gr\xE2ce \xE0 TyroServ et tr\xE8s peu de moyens. Un faux d\xE9part avec la crypto, une explosion en 2025, et en 2026, tout Tyrolium se r\xE9organise autour de ses revenus r\xE9currents.",summaryEn:"SolidServ was born in 2022 from an idea by Pierre-Louis, with servers bought thanks to TyroServ and very few resources. A false start with crypto, a boom in 2025, and in 2026 all of Tyrolium reorganises around its recurring revenue.",headline:{value:"MRR",title:"devenu le moteur financier du groupe",titleEn:"now the group's financial engine"},heroStats:[{value:"2022",title:"Lancement de SolidServ",titleEn:"SolidServ launch"},{value:"2025",title:"L'ann\xE9e de l'explosion",titleEn:"The breakout year"},{value:String(n.length),title:"Serveurs et instances d\xE9ploy\xE9s par le groupe",titleEn:"Servers and instances deployed by the group"},{value:"2,99 \u20AC",valueEn:"\u20AC2.99",title:"Premier prix, par mois",titleEn:"Entry price, per month"}],facts:[{label:"Filiale",labelEn:"Subsidiary",value:"SolidServ"},{label:"Lancement",labelEn:"Launch",value:"Mai 2022",valueEn:"May 2022"},{label:"L'id\xE9e",labelEn:"The idea",value:"Pierre-Louis, ancien d'un petit h\xE9bergeur",valueEn:"Pierre-Louis, formerly at a small host"},{label:"Offres",labelEn:"Offers",value:"VPS, serveurs d\xE9di\xE9s, Minecraft, FiveM, h\xE9bergement web",valueEn:"VPS, dedicated servers, Minecraft, FiveM, web hosting"},{label:"Mod\xE8le",labelEn:"Model",value:"Abonnement mensuel (MRR)",valueEn:"Monthly subscription (MRR)"},{label:"Machines",labelEn:"Hardware",value:"Achet\xE9es, pas lou\xE9es",valueEn:"Bought, not rented"}],link:{label:"solidserv.fr",url:"https://solidserv.fr"},blocks:[{type:"text",label:"Le contexte",labelEn:"The context",title:"Une id\xE9e venue de l'int\xE9rieur d'un h\xE9bergeur.",titleEn:"An idea from inside a hosting company.",paragraphs:["En 2022, TyroServ a permis d'acheter nos propres serveurs. Restait une question : que faire de cette infrastructure en dehors de nos projets ?","L'id\xE9e vient de Pierre-Louis, l'un des cofondateurs historiques. Il avait travaill\xE9 quelque temps chez un petit h\xE9bergeur : il savait comment ce m\xE9tier fonctionne de l'int\xE9rieur, ce qu'il co\xFBte et ce qu'il rapporte. Le 24 mars 2022, le projet SolidServ est cr\xE9\xE9. Le 7 mai, les premiers serveurs sont en ligne."],paragraphsEn:["In 2022, TyroServ had paid for our own servers. One question remained: what to do with that infrastructure beyond our own projects?","The idea came from Pierre-Louis, one of the historical co-founders. He had worked for a while at a small hosting company: he knew how the business works from the inside, what it costs and what it earns. On 24 March 2022, the SolidServ project was created. On 7 May, the first servers went live."],linkLabel:"Lire l'\xE9tude de cas TyroServ",linkLabelEn:"Read the TyroServ case study",linkRouter:"/etudes-de-cas/tyroserv"},{type:"story",label:"L'anecdote",labelEn:"The story",title:"Au d\xE9but, on acceptait la crypto.",titleEn:"At first, we accepted crypto.",paragraphs:["Pour se d\xE9marquer au lancement, notre strat\xE9gie \xE9tait simple : proposer des serveurs payables en cryptomonnaie. Sur le papier, c'\xE9tait un argument que peu d'h\xE9bergeurs avaient.","Dans les faits, \xE7a ne nous a ramen\xE9 que des clients dont nous ne voulions pas. Nous avons arr\xEAt\xE9. Aujourd'hui, SolidServ n'accepte plus la crypto, et nous choisissons nos clients autant qu'ils nous choisissent."],paragraphsEn:["To stand out at launch, our strategy was simple: offer servers payable in cryptocurrency. On paper, it was a selling point few hosts had.","In practice, it only brought us customers we did not want. We stopped. Today, SolidServ no longer accepts crypto, and we choose our customers as much as they choose us."],author:"Maxime Tournier",authorRole:"PDG & Fondateur de Tyrolium",authorRoleEn:"CEO & Founder of Tyrolium"},{type:"features",label:"Dans la gal\xE8re",labelEn:"In hard times",title:"Construit sans lev\xE9e de fonds.",titleEn:"Built without raising funds.",paragraphs:["SolidServ ne s'est pas construit avec un gros budget. Il s'est construit avec ce que nous avions : les machines achet\xE9es gr\xE2ce \xE0 TyroServ, une \xE9quipe r\xE9duite, et l'envie de ne d\xE9pendre de personne."],paragraphsEn:["SolidServ was not built on a big budget. It was built with what we had: the machines bought thanks to TyroServ, a small team, and the will to depend on no one."],items:[{icon:"ri-server-fill",title:"Des machines \xE0 nous",titleEn:"Our own machines",desc:"Achet\xE9es, pas lou\xE9es : au si\xE8ge de D\xE9cines, et en baies dans des datacenters en France.",descEn:"Bought, not rented: at our D\xE9cines headquarters, and in racks in French datacenters."},{icon:"ri-hand-coin-fill",title:"Aucun investisseur",titleEn:"No investors",desc:"Chaque nouvelle capacit\xE9 a \xE9t\xE9 financ\xE9e par les revenus du groupe.",descEn:"Every new bit of capacity was funded by the group's own revenue."},{icon:"ri-stack-fill",title:"Une mont\xE9e progressive",titleEn:"Step-by-step growth",desc:"Nous avons augment\xE9 notre capacit\xE9 au rythme des clients, jamais avant.",descEn:"We grew our capacity at the pace of our customers, never ahead of it."}]},{type:"server-fleet",label:"Le parc en temps r\xE9el",labelEn:"Live server fleet",title:`${n.length} serveurs et instances d\xE9ploy\xE9s.`,titleEn:`${n.length} servers and instances deployed.`,paragraphs:["Notre r\xE8gle est simple : nous h\xE9bergeons en France (Strasbourg, Gravelines, D\xE9cines-Charpieu, Lyon, Blainville). Mais quand un client ou un projet a un besoin sp\xE9cifique \xE0 l'international : r\xE9seau, VPN, redirection de paquets ou proximit\xE9 g\xE9ographique, nous avons la capacit\xE9 de d\xE9ployer hors de nos fronti\xE8res, comme \xE0 Francfort, Tokyo ou Toronto."],paragraphsEn:["Our rule is simple: we host in France (Strasbourg, Gravelines, D\xE9cines-Charpieu, Lyon, Blainville). Still, when a client or project has a specific international requirement : networking, VPN, packet routing or geographic proximity, we have the capacity to deploy abroad, including in Frankfurt, Tokyo and Toronto."],serverGroups:d,serverLocations:m,serverTotal:n.length,note:"Donn\xE9es synchronis\xE9es dynamiquement avec l'inventaire public de notre page Serveurs.",noteEn:"Data dynamically synced with the public inventory on our Servers page.",linkLabel:"Explorer les "+n.length+" serveurs en d\xE9tail",linkLabelEn:"Explore all "+n.length+" servers in detail",linkRouter:"/server"},{type:"steps",label:"La trajectoire",labelEn:"The trajectory",title:"Lancement, explosion, strat\xE9gie.",titleEn:"Launch, breakout, strategy.",items:[{title:"2022 \xB7 Le lancement",titleEn:"2022 \xB7 The launch",desc:"SolidServ ouvre avec nos premi\xE8res machines. Les d\xE9buts sont modestes, et marqu\xE9s par le faux d\xE9part de la crypto.",descEn:"SolidServ opens with our first machines. The start is modest, and marked by the crypto false start."},{title:"2023 \u2013 2024 \xB7 La mont\xE9e en capacit\xE9",titleEn:"2023 \u2013 2024 \xB7 Scaling up",desc:"Nous augmentons progressivement notre infrastructure, au rythme de la demande.",descEn:"We gradually grow our infrastructure, at the pace of demand."},{title:"2025 \xB7 L'explosion",titleEn:"2025 \xB7 The breakout",desc:"La demande d\xE9colle. SolidServ cesse d'\xEAtre un projet annexe et devient une activit\xE9 \xE0 part enti\xE8re.",descEn:"Demand takes off. SolidServ stops being a side project and becomes a business in its own right."},{title:"2026 \xB7 Tout Tyrolium passe au MRR",titleEn:"2026 \xB7 All of Tyrolium moves to MRR",desc:"Le revenu mensuel r\xE9current devient l'objectif de tout le groupe, et SolidServ en est le c\u0153ur.",descEn:"Monthly recurring revenue becomes the goal of the whole group, with SolidServ at its core."}]},{type:"features",label:"Le virage",labelEn:"The shift",title:"Du chiffre ponctuel au revenu r\xE9current.",titleEn:"From one-off revenue to recurring revenue.",paragraphs:["Pendant des ann\xE9es, ce qui finan\xE7ait Tyrolium, c'\xE9taient les prestations web et la formation : des missions qui rapportent une fois, puis qu'il faut retrouver. Aujourd'hui, c'est le revenu mensuel r\xE9current de SolidServ."],paragraphsEn:["For years, what funded Tyrolium was web services and training: jobs that pay once, and then have to be found again. Today, it is the monthly recurring revenue of SolidServ."],items:[{icon:"ri-history-fill",title:"Hier : la prestation",titleEn:"Yesterday: one-off jobs",desc:"Sites web et formations, factur\xE9s \xE0 la mission. Un bon mois ne garantit pas le suivant.",descEn:"Websites and training, billed per job. A good month does not guarantee the next."},{icon:"ri-repeat-fill",title:"Aujourd'hui : l'abonnement",titleEn:"Today: subscriptions",desc:"Chaque client h\xE9berg\xE9 rapporte chaque mois. Le revenu s'additionne au lieu de repartir de z\xE9ro.",descEn:"Every hosted customer pays every month. Revenue adds up instead of starting from zero."},{icon:"ri-links-fill",title:"La prestation dilu\xE9e dans le serveur",titleEn:"Services folded into hosting",desc:"Nos prestations web ne sont plus vendues seules : elles sont int\xE9gr\xE9es \xE0 un abonnement d'h\xE9bergement.",descEn:"Our web services are no longer sold on their own: they are bundled into a hosting subscription."}]},{type:"compare",label:"Pourquoi \xE7a marche",labelEn:"Why it works",title:"Trois mod\xE8les \xE9conomiques, une seule \xE9quation gagnante.",titleEn:"Three business models, one winning equation.",columns:[{name:"Prestation web one-shot",nameEn:"One-off web service"},{name:"Revendeur qui loue ses serveurs",nameEn:"Reseller renting servers"},{name:"Mod\xE8le SolidServ (MRR)",nameEn:"SolidServ model (MRR)",highlight:!0}],rows:[{label:"Revenu mensuel r\xE9current qui s'additionne",labelEn:"Compounding monthly recurring revenue",values:[!1,!0,!0]},{label:"Machines poss\xE9d\xE9es en propre (co\xFBt marginal quasi nul)",labelEn:"Owned hardware (near-zero marginal cost)",values:[!1,!1,!0]},{label:"Possibilit\xE9 d'offrir la cr\xE9ation du site au client",labelEn:"Ability to offer website creation for free",values:[!1,!1,!0]},{label:"Capacit\xE9 de d\xE9ploiement en France et \xE0 l'international",labelEn:"Deployment capacity in France and internationally",values:[!1,!0,!0]}]},{type:"text",label:"En pratique",labelEn:"In practice",title:"Le site est offert, l'h\xE9bergement fait le reste.",titleEn:"The website is free; hosting does the rest.",paragraphs:["Diluer la prestation dans le serveur, c'est par exemple notre partenariat avec le Cabinet Marthelot : le site vitrine est offert au client, et c'est l'abonnement d'h\xE9bergement SolidServ qui rembourse la cr\xE9ation, puis devient un revenu r\xE9current.","Ce mod\xE8le n'est possible que parce que nos machines nous appartiennent. Un h\xE9bergeur qui loue ses serveurs paie chaque site chaque mois : il ne peut pas se permettre d'offrir le d\xE9veloppement."],paragraphsEn:["Folding services into hosting means, for example, our partnership with Cabinet Marthelot: the showcase website is free for the client, and the SolidServ hosting subscription pays back the build, then becomes recurring revenue.","This model only works because we own our machines. A host that rents its servers pays for every site every month: it cannot afford to give the build away."],linkLabel:"Lire l'\xE9tude de cas Cabinet Marthelot",linkLabelEn:"Read the Cabinet Marthelot case study",linkRouter:"/etudes-de-cas/cabinet-marthelot"},{type:"testimonial",quote:"M\xEAme quand ce n'est pas facile, tu n'as jamais abandonn\xE9, et c'est admirable. Je pense sinc\xE8rement que tu es fait pour tracer ton propre chemin et pas pour \xEAtre salari\xE9.",quoteEn:"Even when things get tough, you have never given up, and that is admirable. I truly believe you are meant to carve your own path, not to be an employee.",author:"Pierre-Louis Devaud",authorRole:"Cofondateur de SolidServ \xB7 Cofondateur historique de TyroServ",authorRoleEn:"Co-founder of SolidServ \xB7 Historic co-founder of TyroServ",photo:"assets/teams/Pierre-Louis_Devaud.jpg"},{type:"features",label:"Les le\xE7ons",labelEn:"The lessons",title:"Ce que nous en retenons.",titleEn:"What we take away.",items:[{icon:"ri-user-search-fill",title:"L'exp\xE9rience terrain vaut un business plan",titleEn:"Field experience beats a business plan",desc:"SolidServ est n\xE9 de quelqu'un qui avait vu le m\xE9tier de l'int\xE9rieur.",descEn:"SolidServ was born from someone who had seen the trade from the inside."},{icon:"ri-forbid-2-fill",title:"Un mauvais client co\xFBte plus qu'il ne rapporte",titleEn:"A bad customer costs more than they pay",desc:"La crypto nous a appris \xE0 choisir nos clients plut\xF4t qu'\xE0 les accumuler.",descEn:"Crypto taught us to choose our customers rather than pile them up."},{icon:"ri-repeat-fill",title:"Le r\xE9current finance l'avenir",titleEn:"Recurring revenue funds the future",desc:"Un revenu qui revient chaque mois permet de planifier, d'investir et de dire non.",descEn:"Revenue that comes back every month lets you plan, invest and say no."}]}],cta:{title:"Vous cherchez un h\xE9bergement ?",titleEn:"Looking for hosting?",content:"VPS, serveurs d\xE9di\xE9s, serveurs de jeu ou sites web : h\xE9bergez vos projets sur des machines qui nous appartiennent, en France.",contentEn:"VPS, dedicated servers, game servers or websites: host your projects on machines we own, in France.",btn:"D\xE9couvrir nos offres serveurs",btnEn:"Discover our server offers",btnIcon:"ri-server-line",routerLink:"/prestation/server"}},{slug:"tyrolium-ui",publishedAt:"2026-10-16",brand:"Tyrolium UI",logo:"assets/tyrolium-ui/projects/Tyrolium-White.png",partnerCombo:{logo:"assets/tyrolium-ui/projects/Tyrolium-White.png",group:"Tyrolium",name:"Design System"},gradient:"linear-gradient(135deg, #0000FF 0%, #BF0000 100%)",category:"Design \xB7 Identit\xE9",categoryEn:"Design \xB7 Identity",period:"2017 \u2013 2026",dataAsOf:"octobre 2026",dataAsOfEn:"October 2026",title:"Nous avons fusionn\xE9 nos identit\xE9s. Presque tout le monde \xE9tait contre.",titleEn:"We merged our identities. Almost everyone was against it.",summary:"Pendant des ann\xE9es, chaque id\xE9e de Tyrolium avait son site, sa charte et son back-office. En juillet 2026, pour nos 9 ans, tout a converg\xE9 : une API, un back-office, une identit\xE9 forte et une librairie de composants partag\xE9e par toutes les filiales. Le choix le plus critiqu\xE9 de notre histoire.",summaryEn:"For years, every Tyrolium idea had its own website, brand guidelines and back office. In July 2026, for our 9th anniversary, everything converged: one API, one back office, one strong identity and a component library shared by every subsidiary. The most criticised choice in our history.",headline:{value:"1",title:"identit\xE9 pour tout le groupe",titleEn:"identity for the whole group"},heroStats:[{value:"9 ans",valueEn:"9 years",title:"Pour arriver \xE0 une seule identit\xE9",titleEn:"To reach a single identity"},{value:"5",title:"Projets maintenus apr\xE8s 2023",titleEn:"Projects kept after 2023"},{value:"4",title:"Piliers : API, back-office, identit\xE9, librairie",titleEn:"Pillars: API, back office, identity, library"},{value:"1",title:"Compte Useritium pour tous les services",titleEn:"Useritium account for every service"}],facts:[{label:"Sujet",labelEn:"Topic",value:"Unification de l'identit\xE9 du groupe",valueEn:"Unifying the group's identity"},{label:"Aboutissement",labelEn:"Milestone",value:"Juillet 2026, pour les 9 ans",valueEn:"July 2026, for the 9th anniversary"},{label:"Socle",labelEn:"Foundation",value:"Une API, un back-office, une librairie, une identit\xE9",valueEn:"One API, one back office, one library, one identity"},{label:"Comptes",labelEn:"Accounts",value:"Useritium, partout",valueEn:"Useritium, everywhere"},{label:"Documentation",labelEn:"Documentation",value:"design.tyrolium.fr"}],link:{label:"design.tyrolium.fr",url:"https://design.tyrolium.fr"},blocks:[{type:"text",label:"Avant",labelEn:"Before",title:"Une id\xE9e, un site, une charte, un back-office.",titleEn:"One idea, one website, one brand, one back office.",paragraphs:["Pendant des ann\xE9es, chaque nouvelle id\xE9e de Tyrolium devenait un projet \xE0 part : son propre site, sa propre direction artistique, son propre back-office. C'\xE9tait rapide pour d\xE9marrer, et impossible \xE0 maintenir.","Les logos en sont la meilleure preuve. Le premier logo de Tyrolium dure presque trois ans avant d'\xEAtre remplac\xE9 en 2021, en m\xEAme temps que le nom passe de \xAB Tyrolium Entertainment \xBB \xE0 \xAB Tyrolium \xBB. TyroMusic change de logo en 2020, devient S\xE9l\xE9musium en 2021 avec une toute nouvelle charte, puis change encore de logo en 2022. En ao\xFBt 2021, trois projets changent de logo le m\xEAme jour. TyroStudio passe d'un ph\xE9nix en 2020 \xE0 un nouveau logo en 2025, avant de devenir TyroCiel en 2026."],paragraphsEn:["For years, every new Tyrolium idea became a separate project: its own website, its own art direction, its own back office. It was quick to start, and impossible to maintain.",`The logos are the best proof. Tyrolium's first logo lasted almost three years before being replaced in 2021, when the name went from "Tyrolium Entertainment" to "Tyrolium". TyroMusic changed its logo in 2020, became S\xE9l\xE9musium in 2021 with brand-new guidelines, then changed its logo again in 2022. In August 2021, three projects changed their logos on the same day. TyroStudio went from a phoenix in 2020 to a new logo in 2025, before becoming TyroCiel in 2026.`],linkLabel:"Voir la chronologie",linkLabelEn:"See the timeline",linkRouter:"/chronologie"},{type:"logo-evolution",label:"La preuve par l'image",labelEn:"Visual proof",title:"Trois projets, trois mondes qui n'avaient rien en commun.",titleEn:"Three projects, three worlds that had nothing in common.",paragraphs:["Avant la refonte, rien ne permettait de deviner que ces trois marques appartenaient au m\xEAme groupe : ni les formes, ni les couleurs, ni les typographies. En 2026, chacune a gard\xE9 son symbole, mais toutes parlent d\xE9sormais la m\xEAme langue visuelle."],paragraphsEn:["Before the overhaul, nothing suggested that these three brands belonged to the same group: neither shapes, nor colours, nor typography. In 2026, each kept its own symbol, but they all speak the same visual language."],evolutions:[{oldName:"Tyrolium Ent.",oldPeriod:"2019 \u2013 2021",oldLogo:"assets/etudes/tyrolium-ui/tyrolium-old.png",newName:"Tyrolium",newPeriod:"Depuis 2026",newPeriodEn:"Since 2026",newLogo:"assets/tyrolium-ui/projects/Tyrolium.png",desc:"Du bleu plat des d\xE9buts au d\xE9grad\xE9 bleu-rouge et aux reliefs de la holding.",descEn:"From the flat blue of the early days to the holding's blue-red gradient and depth."},{oldName:"TyroStudio",oldPeriod:"2020 \u2013 2025",oldLogo:"assets/etudes/tyrolium-ui/tyrostudio-old.png",newName:"TyroCiel",newPeriod:"Depuis 2026",newPeriodEn:"Since 2026",newLogo:"assets/tyrolium-ui/projects/TyroCiel.png",desc:"Du ph\xE9nix rose isol\xE9 \xE0 l'\xE9toile de TyroCiel, hommage \xE0 Loriciel align\xE9 sur le groupe.",descEn:"From the isolated pink phoenix to TyroCiel's star, a tribute to Loriciel aligned with the group."},{oldName:"Influnias",oldPeriod:"2022 \u2013 2026",oldLogo:"assets/etudes/tyrolium-ui/influnias-old.png",newName:"Influnias",newPeriod:"Depuis 2026",newPeriodEn:"Since 2026",newLogo:"assets/tyrolium-ui/projects/Influnias.png",desc:"D'un logotype vertical pastel sans lien avec Tyrolium \xE0 un symbole g\xE9om\xE9trique unifi\xE9.",descEn:"From a vertical pastel wordmark unrelated to Tyrolium to a unified geometric symbol."}]},{type:"story",label:"2023",labelEn:"2023",title:"L'ann\xE9e o\xF9 tout s'est arr\xEAt\xE9.",titleEn:"The year everything stopped.",paragraphs:["En janvier 2023, j'ai restructur\xE9 toute la holding. Nous nous sommes s\xE9par\xE9s d'\xE9norm\xE9ment de personnes, et nous avons ferm\xE9 une grande partie de nos filiales. Seuls TyroServ, Influnias, SolidServ, TyroCiel et Gamenium ont \xE9t\xE9 maintenus.","La dispersion avait un co\xFBt. Chaque projet avait sa charte, son site, ses outils, et plus personne ne pouvait tout faire tenir. C'est de l\xE0 qu'est partie l'id\xE9e d'un socle commun."],paragraphsEn:["In January 2023, I restructured the entire holding. We parted ways with a great many people, and we closed a large share of our subsidiaries. Only TyroServ, Influnias, SolidServ, TyroCiel and Gamenium were kept.","Spreading ourselves thin had a cost. Every project had its own brand, website and tools, and no one could hold it all together anymore. That is where the idea of a common foundation came from."],author:"Maxime Tournier",authorRole:"PDG & Fondateur de Tyrolium",authorRoleEn:"CEO & Founder of Tyrolium"},{type:"features",label:"Aujourd'hui",labelEn:"Today",title:"Un socle, quatre piliers.",titleEn:"One foundation, four pillars.",paragraphs:["Plut\xF4t que de multiplier les outils, nous avons tout uniformis\xE9. Chaque filiale s'appuie d\xE9sormais sur la m\xEAme base."],paragraphsEn:["Instead of multiplying tools, we standardised everything. Every subsidiary now relies on the same foundation."],items:[{icon:"ri-git-merge-fill",title:"Une seule API",titleEn:"One API",desc:"Toutes les filiales parlent \xE0 la m\xEAme API, au lieu d'un serveur par projet.",descEn:"Every subsidiary talks to the same API, instead of one server per project."},{icon:"ri-dashboard-3-fill",title:"Un seul back-office",titleEn:"One back office",desc:"Offres, clients, sites, comptes : tout se g\xE8re depuis un back-office interne unique.",descEn:"Offers, customers, websites, accounts: everything is managed from a single internal back office."},{icon:"ri-fingerprint-fill",title:"Une identit\xE9 forte",titleEn:"A strong identity",desc:"Une charte commune et un compte Useritium unique, de TyroServ \xE0 NexiumiaCRM.",descEn:"Shared brand guidelines and a single Useritium account, from TyroServ to NexiumiaCRM."},{icon:"ri-layout-masonry-fill",title:"Une librairie partag\xE9e",titleEn:"A shared library",desc:"Tyrolium UI, nos composants communs, document\xE9s et disponibles sur design.tyrolium.fr.",descEn:"Tyrolium UI, our shared components, documented and available on design.tyrolium.fr."}]},{type:"compare",label:"Le basculement",labelEn:"The shift",title:"De l'archipel au syst\xE8me.",titleEn:"From an archipelago to a system.",columns:[{name:"Avant (2017 \u2013 2025)",nameEn:"Before (2017 \u2013 2025)"},{name:"Depuis Tyrolium UI (2026)",nameEn:"Since Tyrolium UI (2026)",highlight:!0}],rows:[{label:"Charte graphique et typographies communes",labelEn:"Shared brand guidelines and typography",values:[!1,!0]},{label:"Librairie de composants partag\xE9e (Tyrolium UI)",labelEn:"Shared component library (Tyrolium UI)",values:[!1,!0]},{label:"Compte utilisateur unique (Useritium)",labelEn:"Single user account (Useritium)",values:[!1,!0]},{label:"API et back-office centralis\xE9s",labelEn:"Centralised API and back office",values:[!1,!0]},{label:"Une correction d\xE9ploy\xE9e sur tous les sites d'un coup",labelEn:"A fix deployed across every website at once",values:[!1,!0]}]},{type:"text",label:"Juillet 2026",labelEn:"July 2026",title:"Les 9 ans : l'aboutissement.",titleEn:"The 9th anniversary: the culmination.",paragraphs:["Pour les 9 ans de Tyrolium, nous avons refait toute l'identit\xE9 visuelle : nouveau design system, nouveaux logos et nouvelle charte pour Tyrolium et l'ensemble de ses filiales. C'est l'aboutissement de tout ce que le groupe a construit depuis 2017.","Un mois plus t\xF4t, en juin 2026, Tyrolium avait abandonn\xE9 l'\xE9tiquette d'\xAB entreprise multisectorielle \xBB pour se pr\xE9senter officiellement comme une holding technologique. Une holding, une identit\xE9."],paragraphsEn:["For Tyrolium's 9th anniversary, we rebuilt the entire visual identity: a new design system, new logos and new guidelines for Tyrolium and all its subsidiaries. It is the culmination of everything the group has built since 2017.",'A month earlier, in June 2026, Tyrolium had dropped the "multi-sector company" label to officially present itself as a tech holding. One holding, one identity.']},{type:"story",label:"Le choix critiqu\xE9",labelEn:"The criticised choice",title:"La plupart des t\xEAtes pensantes n'en voulaient pas.",titleEn:"Most of our leading minds did not want it.",paragraphs:["Il faut l'avouer : ce choix a \xE9t\xE9 tr\xE8s critiqu\xE9, au sein m\xEAme de Tyrolium. La plupart des t\xEAtes pensantes du groupe n'en voulaient pas. Fusionner les identit\xE9s d'un studio de jeu vid\xE9o, d'un h\xE9bergeur, d'une agence de VTubers et d'un CRM, sur le papier, \xE7a ne va pas ensemble.","Je l'ai fait quand m\xEAme, et je pense avoir trouv\xE9 un bon \xE9quilibre. Le socle est commun : la typographie, les composants, la structure des sites. Mais chaque filiale garde son logo, sa couleur et son ton. On reconna\xEEt Tyrolium partout, sans confondre TyroCiel avec SolidServ."],paragraphsEn:["We have to admit it: this choice was heavily criticised, even inside Tyrolium. Most of the group's leading minds did not want it. Merging the identities of a video game studio, a hosting company, a VTuber agency and a CRM does not, on paper, fit together.","I did it anyway, and I think I found a good balance. The foundation is shared: the typography, the components, the structure of the websites. But each subsidiary keeps its logo, its colour and its tone. You recognise Tyrolium everywhere, without mistaking TyroCiel for SolidServ."],author:"Maxime Tournier",authorRole:"PDG & Fondateur de Tyrolium",authorRoleEn:"CEO & Founder of Tyrolium"},{type:"brand-grid",label:"L'\xE9cosyst\xE8me unifi\xE9",labelEn:"The unified ecosystem",title:"Une holding, huit filiales, une seule signature.",titleEn:"One holding, eight subsidiaries, a single signature.",paragraphs:["Chaque entit\xE9 poss\xE8de son propre embl\xE8me, mais toutes partagent d\xE9sormais le m\xEAme ADN g\xE9om\xE9trique, le m\xEAme d\xE9grad\xE9 et la m\xEAme architecture Typo (Noto Sans Display + Syne + Inter)."],paragraphsEn:["Each entity has its own emblem, yet they all share the same geometric DNA, the same gradient and the same typographic architecture (Noto Sans Display + Syne + Inter)."],brands:[{name:"Tyrolium",role:"Maison m\xE8re \xB7 Holding technologique",roleEn:"Parent company \xB7 Tech holding",logo:"assets/tyrolium-ui/projects/Tyrolium.png",url:"tyrolium.fr",parent:!0},{name:"SolidServ",role:"H\xE9bergeur de serveurs",roleEn:"Server hosting",logo:"assets/tyrolium-ui/projects/SolidServ.png",url:"solidserv.fr"},{name:"TyroServ",role:"Serveur Minecraft",roleEn:"Minecraft server",logo:"assets/tyrolium-ui/projects/TyroServ.png",url:"tyroserv.fr"},{name:"TyroCiel",role:"Studio de jeu-vid\xE9o",roleEn:"Video game studio",logo:"assets/tyrolium-ui/projects/TyroCiel.png",url:"tyrociel.fr"},{name:"Gamenium",role:"M\xE9dia & actu jeu-vid\xE9o",roleEn:"Gaming news media",logo:"assets/tyrolium-ui/projects/Gamenium.png",url:"gamenium.fr"},{name:"Useritium",role:"Comptes utilisateurs",roleEn:"User accounts",logo:"assets/tyrolium-ui/projects/Useritium.png",url:"useritium.fr"},{name:"NexiumiaCRM",role:"Logiciel CRM",roleEn:"CRM software",logo:"assets/tyrolium-ui/projects/NexiumiaCRM.png",url:"nexiumiacrm.fr"},{name:"Influnias",role:"Agence d'influenceurs",roleEn:"Influencer agency",logo:"assets/tyrolium-ui/projects/Influnias.png",url:"influnias.fr"},{name:"Vturias",role:"Agence de VTubers",roleEn:"VTuber agency",logo:"assets/tyrolium-ui/projects/Vturias.png",url:"vturias.fr"}],linkLabel:"Explorer le Media Kit complet",linkLabelEn:"Explore the full Media Kit",linkRouter:"/mediakit"},{type:"features",label:"Le r\xE9sultat",labelEn:"The result",title:"Moins \xE0 maintenir, plus de synergie.",titleEn:"Less to maintain, more synergy.",paragraphs:["Le vrai gain n'est pas visible de l'ext\xE9rieur. Il est dans tout ce que nous n'avons plus \xE0 faire en double, et dans tout ce que les filiales peuvent d\xE9sormais faire ensemble."],paragraphsEn:["The real gain is not visible from the outside. It lies in everything we no longer have to do twice, and in everything the subsidiaries can now do together."],items:[{icon:"ri-tools-fill",title:"Corriger une fois, partout",titleEn:"Fix once, everywhere",desc:"Une correction ou une am\xE9lioration sur un composant profite imm\xE9diatement \xE0 tous les sites du groupe.",descEn:"A fix or an improvement to a component instantly benefits every website in the group."},{icon:"ri-time-fill",title:"Du temps rendu aux projets",titleEn:"Time given back to projects",desc:"Moins de sites, de chartes et de back-offices \xE0 maintenir, c'est plus de temps pour d\xE9velopper les produits.",descEn:"Fewer websites, guidelines and back offices to maintain means more time to build the products."},{icon:"ri-team-fill",title:"Des \xE9quipes qui circulent",titleEn:"Teams that move freely",desc:"M\xEAmes outils, m\xEAme structure : passer d'une filiale \xE0 l'autre ne demande plus de tout r\xE9apprendre.",descEn:"Same tools, same structure: moving from one subsidiary to another no longer means relearning everything."},{icon:"ri-share-forward-fill",title:"Des filiales qui se renforcent",titleEn:"Subsidiaries that strengthen each other",desc:"Un compte Useritium, une identit\xE9 reconnaissable : un utilisateur d'une filiale d\xE9couvre naturellement les autres.",descEn:"One Useritium account, one recognisable identity: a user of one subsidiary naturally discovers the others."}]},{type:"features",label:"Les le\xE7ons",labelEn:"The lessons",title:"Ce que nous en retenons.",titleEn:"What we take away.",items:[{icon:"ri-focus-3-fill",title:"Une marque forte vaut mieux que dix faibles",titleEn:"One strong brand beats ten weak ones",desc:"Chaque logo chang\xE9, chaque charte abandonn\xE9e \xE9tait de l'\xE9nergie perdue.",descEn:"Every changed logo, every abandoned guideline was wasted energy."},{icon:"ri-contrast-2-fill",title:"Uniformiser n'est pas effacer",titleEn:"Standardising is not erasing",desc:"Un socle commun laisse \xE0 chaque filiale son logo, sa couleur et sa personnalit\xE9.",descEn:"A shared foundation leaves each subsidiary its logo, colour and personality."},{icon:"ri-compass-3-fill",title:"Un choix impopulaire peut \xEAtre le bon",titleEn:"An unpopular choice can be the right one",desc:"\xC9couter les critiques, oui. Renoncer \xE0 une vision parce qu'elle d\xE9range, non.",descEn:"Listen to criticism, yes. Give up on a vision because it is uncomfortable, no."}],linkLabel:"D\xE9couvrir notre vision",linkLabelEn:"Discover our vision",linkRouter:"/vision"}],cta:{title:"Votre marque se disperse ?",titleEn:"Is your brand spreading thin?",content:"Site, identit\xE9, outils : nous construisons des projets web sur un socle solide, pens\xE9 pour durer.",contentEn:"Website, identity, tools: we build web projects on a solid foundation, designed to last.",btn:"D\xE9couvrir nos prestations web",btnEn:"Discover our web services",btnIcon:"ri-palette-line",routerLink:"/prestation/web"}}];function v(t){return h.find(e=>e.slug===t)}export{h as a,v as b};
